(function () {
/* ===== 1_core.js ===== */
/* ============================================================================
 * Anti-Route v6.0 — 1/4 Core
 * 宿主 / 存储 / 模型归一化 / 保护区 / 静态区选择
 * 设计来自 v5/v6/v7 的实战教训
 * ========================================================================== */

var VERSION = '1.3';
var TAG = '[AR6]';
var CFG_KEY = 'ar6.cfg';
var LOG_KEY = 'ar6.log';
var MAX_LOG = 40;

/* ---------------- 宿主 ---------------- */

function resolveHostWindow() {
  var cands = [];
  try { if (window.top) cands.push(window.top); } catch (e) {}
  try { if (window.parent) cands.push(window.parent); } catch (e) {}
  cands.push(window);
  for (var i = 0; i < cands.length; i++) {
    var w = cands[i];
    try {
      if (w && w.document && w.document.body && w.document.documentElement) return w;
    } catch (e) {}
  }
  return window;
}

/* 脚本自己所在的 window —— 酒馆助手的 eventOn/getButtonEvent 通常注入在这一层 */
var SELF_WIN = null;
try {
  SELF_WIN = (typeof window !== 'undefined' && window) ? window
    : ((typeof globalThis !== 'undefined') ? globalThis : null);
} catch (e) { SELF_WIN = null; }

var HOST = resolveHostWindow();
var DOC = null;
try { DOC = HOST.document; } catch (e) { DOC = null; }
if (!DOC) { try { DOC = document; } catch (e) {} }

/* ---------------- 存储 ---------------- */

var CFG_DEFAULT = {
  enabled: true,          // 总开关
  pin: true,              // 钉死路由参数（删 models[] / allow_fallbacks=false）
  think: 'off',           // off | high（只在字段缺失时补）
  refract: 'off',         // off | light | mid（三轨微扰档位）
  observe: true,          // 零锁观察器
  dualBase: '',           // 双通道指纹：base url
  dualKey: '',            // 双通道指纹：key
  min: false,             // 面板是否收起（关闭态）
  xhr: false,             // 是否挂钩 XMLHttpRequest（默认关；只用 fetch 更稳）
  safe: false,            // 安全模式：完全不挂钩，只留面板与横幅（排查用）
  mx: null,               // 移动端悬浮窗 left（px，null=默认右下）
  my: null,               // 移动端悬浮窗 top
  keep: 30,
  alias: '',              /* 别名钉死：非空时把请求的 model 改写成本值 */
  refractMode: 'stable',  /* stable=同会话固定变形（保前缀缓存）| random=每轮随机（实验） */
  refractSeed: '',        /* 用户盐：改一下，变形结果就换一套 */
  saltWin: 30,            /* 窗口盐：同一聊天在 N 分钟内保持同一套变形（0=关） */
  /* v7.1 破甲：off | safe（只事后补救，不改请求）| strong（改请求 + 事后补救） */
  jail: 'off',
  jailConfirm: true,      /* 补之前先问一句（关掉=自动补） */
  jailMax: 2,             /* 同一轮最多自动续写几次 */
  jailTok: true,          /* 强力档：保底 max_tokens 2048（只加不减） */
  jailSafe: true,         /* 强力档：gemini 系 safetySettings 全 BLOCK_NONE */
  jailPre: false,         /* 强力档：预审框（system + user 各一句） */
  jailText: false,         /* 强力档：输出契约（贴在末条 user 消息尾部） */
  /* v0.6 抗截断：off | light（只提示，不补）| medium（len/cut/pause 补一次） */
  trunc: 'off',
  /* v0.7 抗截断 · 轻档 v2：事前往末条 user 尾部贴提示词（不改参数、不碰响应体、不补写）
     truncLen 只认 0 / 800 / 1200 / 1800（0=关，默认 1200） */
  truncTail: true,         /* L2 收尾契约 */
  truncLen: 1200,          /* L1 字数锚 */
  truncNoCert: true,       /* L3 反自我认证 */
  truncPad: 'off',         /* F 填充锚：off | math */
  truncPadEvery: 2,        /* 填充锚：每 N 段插一条 */
  truncStrip: true,        /* 填充块的显示层剥离 */
  peek: true,              /* 旁路克隆响应体取 model/modelVersion（只读，不阻塞） */
  cardAuto: true,          /* 判为「被换/无思考」时自动弹证据卡 */
  /* v0.82 行为基线：on | off（只提示，不判被换、不进账本；关闸时不写也不判） */
  base: 'on',
  /* v0.84 结构指纹：on | off（只提示；关闸时不写也不判，不进被换率） */
  shape: 'on',
  contentOnly: 'on',     // 只把真正落进聊天的正文算进被换率
  /* v1.3 只查 Gemini：true=只判定 google 家族；false=所有认得出家族的都判定
     （注意：和上面 v0.13 的 scope/scopeList 不是一回事，那组是「按列表过滤」） */
  onlyGemini: true,
  /* v1.3 自动更新：off | check（只查「有没有新版」，不自动下载、不自动替换）
     updUrl 指向一个纯文本或 JSON 的版本文件；留空则只显示「未配置」 */
  upd: 'off',
  updUrl: '',
  /* v0.76 反 OOC：off | on（总闸关时四个子项一律不生效，也不注任何字）
     子项：点名（世界书认人）/ 反模板 / 变更门槛 / 口吻一致。
     oocPolicy 只记冲突弹窗上「以后都按这个来」的全局选择：'' | script | preset */
  ooc: 'off',
  oocRoll: true,
  oocTpl: true,
  oocChg: false,
  oocVoice: true,
  oocPolicy: '',
  /* v8.31 叙述层：off | lite | full（贴在末条 user 消息尾部，只改请求副本） */
  know: 'off',             /* 防全知 */
  knowTip: 'on',           /* 打开防全知前先说明「它会禁止内心话与替人做决定」 */
  charm: 'off',            /* 去媚 */
  /* v0.13 检测范围：只有会被路由的模型才需要判「有没有被换」 */
  helpX: null,
  helpY: null,
  helpBig: false,
  scope: 'all',              /* all=全部都查 | only=只查列表内 | skip=跳过列表内 */
  scopeList: 'deepseek',     /* 逗号分隔关键词，按包含匹配，不分大小写 */
  v: 831,
  fx: 'full',
  rm: false,
  padSeen: false
};

var cfg = null;

function ar6Num(v, def, lo, hi) {
  var n = Number(v);
  if (!isFinite(n)) n = def;
  return Math.max(lo, Math.min(hi, n));
}

function ar6Pick(v, list, def) {
  var s = String(v == null ? '' : v);
  for (var i = 0; i < list.length; i++) if (list[i] === s) return s;
  return def;
}

/* 面板位置记忆消毒：NaN 会写出 left:NaNpx */
function sanitizeFloat(d) {
  if (!d || typeof d !== 'object') return;
  if (typeof d.mx !== 'number' || !isFinite(d.mx)) d.mx = null;
  if (typeof d.my !== 'number' || !isFinite(d.my)) d.my = null;
  d.fx = ar6Pick(d.fx, ['full', 'calm', 'off'], 'full');
  d.rm = !!d.rm;
  d.min = !!d.min;
}

function readCfg() {
  var d = {};
  for (var k in CFG_DEFAULT) d[k] = CFG_DEFAULT[k];
  try {
    var raw = HOST.localStorage.getItem(CFG_KEY);
    if (raw) {
      var s = JSON.parse(raw);
      for (var k2 in s) if (Object.prototype.hasOwnProperty.call(CFG_DEFAULT, k2)) d[k2] = s[k2];
      // 版本迁移：v1 配置没有 refract 字段时，强制回到 off（不沿用旧噪声开关）
      if (!('refract' in s)) d.refract = 'off';
      /* 6.6 迁移：旧版默认开的 XHR 钩子会从旧配置继承下来，强制关掉一次 */
      if (s.v !== 831) {
    d.jailConfirm = true;
        /* 只有 v6 及更早的配置才强制关一次 XHR；v7.0.0 起的用户选择就地保留 */
        if (typeof s.v !== 'number' || s.v < 700) d.xhr = false;
        if (!('peek' in s) || typeof s.v !== 'number' || s.v < 730) d.peek = true;
        if (!('cardAuto' in s)) d.cardAuto = true;
        if (!('alias' in s)) d.alias = '';
        if (!('refractMode' in s)) d.refractMode = 'stable';
        if (!('jail' in s)) d.jail = 'off';
        if (!('jailConfirm' in s)) d.jailConfirm = true;
        if (!('jailMax' in s)) d.jailMax = 2;
        if (!('jailTok' in s)) d.jailTok = true;
        if (!('jailSafe' in s)) d.jailSafe = true;
        if (!('jailPre' in s)) d.jailPre = false;
        if (!('jailText' in s)) d.jailText = false;
        if (!('saltWin' in s)) d.saltWin = 30;
        if (!('know' in s)) d.know = 'off';
        if (!('charm' in s)) d.charm = 'off';
        if (!('helpX' in s)) d.helpX = null;
        if (!('helpY' in s)) d.helpY = null;
        if (!('helpBig' in s)) d.helpBig = false;
        d.v = 831;
        try { HOST.localStorage.setItem(CFG_KEY, JSON.stringify(d)); } catch (e3) {}
      }
    }
  } catch (e) {}
  try { sanitizeFloat(d); } catch (eS) {}
  try { sanitizeTrunc(d); } catch (eT) {}
  return d;
}

/* 稳定种子：同一个 seedStr 永远得到同一个数，用来做「会话内固定」的微扰 */
function hashStr(s) {
  var h = 5381, i;
  s = String(s || '');
  for (i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) | 0;
  return h >>> 0;
}

/* v7.4 窗口盐：同一「聊天 + 时间窗」内保持同一套变形——
   窗内前缀稳定（缓存能命中），跨窗轮换（指纹不固定）。 */
function chatTag() {
  try {
    var c = stCtx();
    if (c) {
      var id = c.chatId || c.chat_id || '';
      if (id) return 'c' + String(id).slice(0, 20);
      var arr = c.chat;
      if (arr && arr.length) {
        var m0 = arr[0] || {};
        var s0 = String(m0.send_date || '') + '|' + String(m0.name || '') + '|' + String(arr.length);
        return 'h' + hashStr(s0);
      }
    }
  } catch (e) {}
  return 'nochat';
}

function saltWindow() {
  var n = Number(cfg.saltWin);
  if (!isFinite(n) || n <= 0) return 0;
  return Math.min(240, Math.round(n));
}

function saltKey(tag) {
  var w = saltWindow();
  var bucket = w ? String(Math.floor(Date.now() / (w * 60000))) : 'free';
  return chatTag() + '|' + bucket + '|' + String(tag || '');
}

function saveCfg() {
  try { HOST.localStorage.setItem(CFG_KEY, JSON.stringify(cfg)); } catch (e) {}
}

function readLog() {
  try {
    var raw = HOST.localStorage.getItem(LOG_KEY);
    if (!raw) return [];
    var arr = JSON.parse(raw);
    return Array.isArray(arr) ? arr : [];
  } catch (e) { return []; }
}

function pushLog(rec) {
  var arr = readLog();
  arr.unshift(rec);              /* 最新在前：面板表格直接取前 N 条 */
  var cap = MAX_LOG;
  if (typeof cfg === 'object' && cfg && cfg.keep) cap = Math.min(MAX_LOG, Math.max(10, cfg.keep));
  if (arr.length > cap) arr.length = cap;
  try { HOST.localStorage.setItem(LOG_KEY, JSON.stringify(arr)); } catch (e) {}
  return arr;
}

cfg = readCfg();

/* ---------------- 模型归一化 ---------------- */

var KNOWN_PREFIX = /^(?:models\/|google\/|openrouter\/|vertex_ai\/|vertex\/|gemini\/|custom\/|litellm\/|fireworks\/|together\/|pggo-|bdgo-|aihubmix-|proxy-|pg-)/;

function normModel(s) {
  var t = String(s == null ? '' : s).trim();
  if (!t) return '';
  try { t = decodeURIComponent(t); } catch (e) {}
  t = t.toLowerCase().split('?')[0].replace(/^https?:\/\/[^/]+\//, '');
  for (var i = 0; i < 6; i++) {
    var before = t;
    t = t.replace(/^[^\x00-\x7f]+[-_\s]*/, '').replace(KNOWN_PREFIX, '');
    if (t === before) break;
  }
  t = t.replace(/:(generatecontent|streamgeneratecontent|counttokens).*$/, '');
  return t.trim();
}

/* 「是不是同一个模型」用的名字归一：剥掉渠道别名与档位后缀。
   -ai / -vertex 是中转给自己标的路由方式，-low / -high 是思考档，都不改变模型身份。
   只用于判等，不改 normModel：档位表还得靠原始名字里的 pro / flash / argon。 */
var ID_TAIL_RE = /[-_.](?:ai|api|vertex|gcp|openai|azure|exp|experimental|preview|latest|thinking|think|nothink|nocot|low|medium|high|minimal|xhigh)$/;
function normModelIdentity(s) {
  var t = normModel(s);
  if (!t) return '';
  for (var i = 0; i < 4; i++) {
    var before = t;
    t = t.replace(ID_TAIL_RE, '');
    /* 日期尾巴：-2025-08-07 / -20250807 / -001 / -v2 */
    t = t.replace(/[-_.](?:v)?\d{1,2}(?:[-_.]\d{1,2}){1,2}$/, '');
    t = t.replace(/[-_.](?:v)?\d{1,4}$/, function (m0) {
      /* 纯数字尾巴只在 ≥3 位或带 v 时剥：别把 gpt-4 / gemini-3 的数字吃掉 */
      return /^[-_.]v/i.test(m0) || /\d{3,}/.test(m0) ? '' : m0;
    });
    if (t === before) break;
  }
  /* 3.0 和 3 是同一条代次线上的两种写法：gemini-3.0-flash ≡ gemini-3-flash。
     不归一的话，渠道换个写法就能被当成「换了模型」。 */
  t = t.replace(/\.0(?=[-_.]|$)/g, '');
  return t;
}

function isOpaqueModel(s) {
  var m = normModel(s);
  if (!m) return true;
  return /^(?:auto|router|default|unknown|any|best|lb)$/.test(m);
}

function isNonChatModel(s) {
  var m = normModel(s);
  return /(?:embedding|embedcontent|imagen|veo|aqa|image-only|tts|audio-only)/.test(m);
}

function isGeminiLike(s) {
  var m = normModel(s);
  if (!m || isOpaqueModel(m)) return false;
  if (/(?:gemma|claude|deepseek|gpt|o1|o3|qwen|llama|glm|ernie)/.test(m)) return false;
  return /gemini/.test(m) || /argon|flash|lite|pro/.test(m) === false ? /gemini/.test(m) : /gemini/.test(m);
}

/* 档位：1=lite/8b, 2=flash, 3=pro, 4=argon/ultra, 0=未知 */
function tierOf(s) {
  var m = normModel(s);
  if (!m || isOpaqueModel(m)) return 0;
  if (/(?:flash[-_. ]?lite|flash[-_. ]?8b|\blite\b|\bnano\b)/.test(m)) return 1;
  if (/\b(?:argon|ultra)\b/.test(m)) return 4;
  if (/\bpro\b/.test(m)) return 3;
  if (/\bflash\b/.test(m)) return 2;
  return 0;
}

/* 代次：gemini-3.1-flash → 3.1，gemini-3-flash → 3，gemini-2.5-pro → 2.5。
   只认「主版本[.次版本]」这种写法，认不出就返回 0（不比代次、不瞎猜）。 */
function genOf(s) {
  var m = normModel(s);
  if (!m || isOpaqueModel(m)) return 0;
  var g = m.match(/(?:^|[-_.])(\d{1,2})(?:[._](\d{1,2}))?(?=[-_.]|$)/);
  if (!g) return 0;
  var maj = Number(g[1]);
  if (!isFinite(maj) || maj <= 0) return 0;
  var min = g[2] == null ? 0 : Number(g[2]);
  if (!isFinite(min) || min < 0 || min > 9) return 0;
  return maj + min / 10;
}

function isProLike(s) {
  var t = tierOf(s);
  return t === 3 || t === 4;
}

/* 厂牌：档位表跨厂牌不可比，先分族再比档 */
function familyOf(s) {
  var m = normModel(s);
  if (!m || isOpaqueModel(m)) return '';
  if (/gemini|gemma|argon|palm\b/.test(m)) return 'google';
  if (/deepseek/.test(m)) return 'deepseek';
  if (/claude|anthropic/.test(m)) return 'anthropic';
  if (/gpt|chatgpt|^o[1-4](?:-|$)|openai/.test(m)) return 'openai';
  if (/qwen|glm|ernie|llama|mistral|kimi|moonshot|doubao|hunyuan|spark/.test(m)) return 'other';
  return '';
}

/* v1.3 检查范围：默认只查 Gemini 家族。
   scope=all 或认不出族（''）时放行——认不出的名字宁可不管，也别乱判。 */
/* v1.3：只查 Gemini 时，「算不算 Gemini」不能只看请求名。
   反代经常把同一个渠道换个名字（请求名写 gpt-4o，后端其实是 gemini），
   只按请求名判会把真 Gemini 也拦掉。规则：
     1) 关掉这个开关 → 什么都查；
     2) 请求名认出是 google → 查；
     3) 请求名认不出（空、别名、router）→ 查（宁可多查，不可漏查）；
     4) 请求名明确是别的家族 → 再看证据里有没有 google，有就查，没有才跳过。 */
function scopeHitGemini(ev) {
  try {
    if (!cfg || cfg.onlyGemini === false) return true;
    var rq = ev && ev.requestedModel ? String(ev.requestedModel) : '';
    var f = rq ? familyOf(rq) : '';
    if (!f) return true;
    if (f === 'google') return true;
    var obs = (ev && ev.observed) || [];
    for (var i = 0; i < obs.length; i++) {
      if (familyOf(String(obs[i] || '')) === 'google') return true;
    }
    return false;
  } catch (e) { return true; }
}

function inScopeModel(s) {
  try {
    if (!cfg || cfg.onlyGemini === false) return true;
    var f = familyOf(s);
    if (!f) return true;
    return f === 'google';
  } catch (e) { return true; }
}

function shortName(s) {
  var m = normModel(s);
  if (!m) return '—';
  return m.length > 26 ? m.slice(0, 25) + '…' : m;
}

/* ---------------- token 估算（CJK 0.85 / 拉丁 1÷3.5 / 其他 0.9） ---------------- */

function estimateTokens(str) {
  if (typeof str !== 'string' || !str) return 0;
  var cjk = 0, latin = 0, other = 0;
  for (var i = 0; i < str.length; i++) {
    var cp = str.codePointAt ? str.codePointAt(i) : str.charCodeAt(i);
    if (cp > 0xffff) i++;
    if (cp >= 0x3400 && cp <= 0x9fff) cjk++;
    else if (cp <= 0x7f) latin++;
    else other++;
  }
  return Math.ceil(cjk * 0.85 + latin / 3.5 + other * 0.9);
}

/* ---------------- 保护区 ----------------
 * 12 类：YAML frontmatter / 代码围栏 / 行内代码 / 酒馆宏 / 状态机标签 / 协议围栏
 *        / XML 标签本身 / 既有注释与引用定义 / URL 与链接 / LaTeX / 引号台词 / 未闭合标签到结尾
 */

var HARD_TAGS = 'UpdateVariable|JSONPatch|jsonpatch|mvu|status|StatusBlock|Status_block|state|panel|options|tool_call|function_call|run_tool_replacement|worldcustomfunction|worldsystem|KonataExtraInformation|IzumiEdit|stat_data|delta_data|variables|StatusPlaceHolderImpl|thinking|think|dream_think|simple_thinking|interleav|Interleaved_thinking|interactive_input';

var SPAN_RULES = [
  /(^|\n)([ \t]{0,3})(`{3,}|~{3,})[^\n]*\n[\s\S]*?\n\2\3[ \t]*(?=\n|$)/g,
  /(`+)([^`\n]+?)\1/g,
  /\{\{[\s\S]{0,4000}?\}\}|<%[\s\S]{0,4000}?%>/g,
  new RegExp('<(' + HARD_TAGS + ')\\b[^>]*>[\\s\\S]*?<\\/\\1\\s*>', 'gi'),
  /<<<\|catgodml\|[\s\S]*?>>>|\[\[IZUMI_CHAT_INDEX_V1\]\]/g,
  /<\/?[A-Za-z\u4e00-\u9fa5][\w:\u4e00-\u9fa5.-]*(?:\s[^<>]{0,400})?>/g,
  /<!--[\s\S]*?-->|^\[\/\/\]:\s*#\s*\([^\n]*\)/gm,
  /\bhttps?:\/\/[^\s<>()]+|!?\[[^\]]*\]\([^)]+\)/g,
  /\$\$[\s\S]*?\$\$|\$[^$\n]{1,400}\$|\\\([\s\S]*?\\\)|\\\[[\s\S]*?\\\]/g,
  /“[^”\n]{1,600}”|「[^」\n]{1,600}」|『[^』\n]{1,600}』|"[^"\n]{1,600}"/g
];

function collectSpans(text) {
  var spans = [];
  if (typeof text !== 'string' || !text) return spans;

  var yaml = /^---[ \t]*\r?\n[\s\S]{1,4000}?\r?\n---[ \t]*(?:\r?\n|$)/.exec(text);
  if (yaml) spans.push([0, yaml[0].length]);

  var trimmed = text.trim();
  if ((trimmed.charAt(0) === '{' && trimmed.slice(-1) === '}') ||
      (trimmed.charAt(0) === '[' && trimmed.slice(-1) === ']')) {
    try { JSON.parse(trimmed); return [[0, text.length]]; } catch (e) {}
  }

  for (var r = 0; r < SPAN_RULES.length; r++) {
    var re = new RegExp(SPAN_RULES[r].source, SPAN_RULES[r].flags);
    var m;
    var guard = 0;
    while ((m = re.exec(text)) !== null && guard++ < 4000) {
      var s = m.index + (m[1] && m[1].length && SPAN_RULES[r] === SPAN_RULES[0] ? m[2].length : 0);
      spans.push([m.index, m.index + m[0].length]);
      if (m[0].length === 0) re.lastIndex++;
    }
  }

  // 未闭合硬标签：从开标签一路保护到结尾
  var openRe = new RegExp('<(' + HARD_TAGS + ')\\b[^>]*>', 'gi');
  var om;
  var oguard = 0;
  while ((om = openRe.exec(text)) !== null && oguard++ < 500) {
    var name = om[1];
    var closeRe = new RegExp('<\\/' + name + '\\s*>', 'i');
    var after = text.slice(om.index + om[0].length);
    if (!closeRe.test(after)) spans.push([om.index, text.length]);
  }

  spans.sort(function (a, b) { return a[0] - b[0] || a[1] - b[1]; });
  var merged = [];
  for (var i = 0; i < spans.length; i++) {
    var cur = spans[i];
    if (cur[1] <= cur[0]) continue;
    if (merged.length && cur[0] <= merged[merged.length - 1][1]) {
      merged[merged.length - 1][1] = Math.max(merged[merged.length - 1][1], cur[1]);
    } else merged.push([cur[0], cur[1]]);
  }
  return merged;
}

function isProtected(spans, start, end) {
  if (!spans || !spans.length) return false;
  var lo = 0, hi = spans.length - 1;
  var qs = Math.min(start, end);
  var qe = Math.max(start + 1, end);
  while (lo <= hi) {
    var mid = (lo + hi) >> 1;
    if (qe <= spans[mid][0]) hi = mid - 1;
    else if (qs >= spans[mid][1]) lo = mid + 1;
    else return true;
  }
  return false;
}

/* ---------------- 静态区评分 ---------------- */

var INSTR_WORDS = /必须|禁止|不得|严禁|请勿|务必|严格|规则|准则|规范|格式|输出|设定|要求|注意|重要|优先|示例|指令|遵循|扮演|描写|文风|字数|段落|\b(?:must|shall|require|format|rule|instruction|guideline|never|do not|output|response|system|character|roleplay|constraint)\b/gi;
var NARR_WORDS = /说道|问道|看着|望向|走进|转身|笑了笑|低声|轻声|沉默|抬头|叹气|眼神|目光|呼吸|手指|窗外|嘴角|点头|摇头|心想|声音|\b(?:said|asked|looked|smiled|whispered|sighed|walked|turned|nodded|eyes|voice|hand|felt|thought)\b/gi;
var QUOTE_RE = /“[^”\n]{2,200}”|「[^」\n]{2,200}」|"[^"\n]{2,200}"/g;
var MARKUP_RE = /^(?:[ \t]*#{1,6}[ \t]+\S|[ \t]*[-+*][ \t]+\S|[ \t]*\d+[.)][ \t]+\S|[ \t]*>[ \t]+\S)|<\/?[A-Za-z][\w:.-]*\b/gm;

function density(text, re) {
  if (!text) return 0;
  var hits = text.match(new RegExp(re.source, re.flags));
  return ((hits ? hits.length : 0) * 1000) / Math.max(80, text.length);
}

function staticScore(node, total) {
  var text = node.text || '';
  if (text.replace(/\s/g, '').length < 40) return -50;
  if (node.isLastUser) return -100;
  if (node.isPrefill) return -90;

  var score = 0;
  var role = node.role;
  if (role === 'system' || role === 'developer') score += 42;
  else if (role === 'user') score += 8;
  else if (role === 'assistant' || role === 'model') score -= 25;

  if (node.index === 0) score += 20;
  else if (node.index < 3) score += 14;

  var ins = density(text, INSTR_WORDS);
  var nar = density(text, NARR_WORDS);
  var quo = density(text, QUOTE_RE);
  var mark = density(text, MARKUP_RE);

  score += Math.min(32, ins * 3.8);
  score += Math.min(16, mark * 2.5);
  score -= Math.min(38, nar * 2.6 + quo * 3.2);
  if (ins >= 3.5 && mark >= 2.0 && nar < 2.0) score += 18;

  return Math.max(-100, Math.min(100, score));
}

function hasRuleMarkup(text) {
  if (typeof text !== 'string' || text.length < 80) return false;
  if (/^[ \t]*#{1,6}[ \t]+\S/m.test(text)) return true;
  var lists = text.match(/^[ \t]*(?:[-+*]|\d+[.)])[ \t]+\S/gm);
  if (lists && lists.length >= 2) return true;
  return /<(?:rules?|instructions?|guidelines?|system|config|writing_style|world_info)\b/i.test(text);
}

/* 历史带：首条 assistant 及其之后（含触发它的那条 user）全部视为历史 */
function findHistoryBand(nodes) {
  var firstAssistant = -1;
  for (var i = 0; i < nodes.length; i++) {
    if (nodes[i].role === 'assistant' || nodes[i].role === 'model') { firstAssistant = i; break; }
  }
  if (firstAssistant < 0) return null;
  var start = firstAssistant;
  for (var j = firstAssistant - 1; j >= 0; j--) {
    if (nodes[j].role === 'user') { start = j; break; }
  }
  var lastUser = -1;
  for (var k = nodes.length - 1; k >= 0; k--) if (nodes[k].isLastUser) { lastUser = k; break; }
  var end = lastUser >= 0 ? lastUser - 1 : nodes.length - 1;
  if (end < start) return null;
  return { start: start, end: end, memberCount: end - start + 1 };
}

/* ---------------- 区选择 ---------------- */

function getMsgText(m) {
  if (!m) return '';
  if (typeof m.content === 'string') return m.content;
  if (Array.isArray(m.content)) {
    for (var i = 0; i < m.content.length; i++) {
      var p = m.content[i];
      if (p && p.type === 'text' && typeof p.text === 'string') return p.text;
    }
  }
  if (typeof m.text === 'string') return m.text;
  return '';
}

function pickZones(inner, channel, maxZones) {
  var zones = [];
  var msgs = Array.isArray(inner.messages) ? inner.messages : null;

  if (!msgs && (Array.isArray(inner.contents) || inner.systemInstruction)) {
    var si = inner.systemInstruction;
    if (si && Array.isArray(si.parts)) {
      for (var p = 0; p < si.parts.length; p++) {
        (function (part) {
          if (!part || typeof part.text !== 'string') return;
          if (part.text.replace(/\s/g, '').length < 60) return;
          zones.push({ get: function () { return part.text; }, set: function (v) { part.text = v; }, score: 100, why: 'systemInstruction.parts[' + p + ']' });
        })(si.parts[p]);
      }
    } else if (si && typeof si.text === 'string' && si.text.replace(/\s/g, '').length >= 60) {
      zones.push({ get: function () { return si.text; }, set: function (v) { si.text = v; }, score: 100, why: 'systemInstruction.text' });
    }
    return zones.slice(0, maxZones);
  }

  if (!msgs || !msgs.length) return zones;

  var lastUserIdx = -1;
  for (var i = msgs.length - 1; i >= 0; i--) {
    var r = String(msgs[i] && msgs[i].role || '').toLowerCase();
    if (r === 'user' && getMsgText(msgs[i]).trim()) { lastUserIdx = i; break; }
  }

  var nodes = [];
  for (var j = 0; j < msgs.length; j++) {
    var m = msgs[j];
    if (!m || typeof m !== 'object') continue;
    var role = String(m.role || 'user').toLowerCase();
    if (role === 'tool' || role === 'function' || m.tool_calls || m.function_call) continue;
    var text = getMsgText(m);
    if (!text || !text.trim()) continue;
    nodes.push({
      index: j, role: role, text: text,
      isLastUser: j === lastUserIdx,
      isPrefill: (role === 'assistant' || role === 'model') && j === msgs.length - 1 && j > lastUserIdx,
      msg: m
    });
  }

  var band = findHistoryBand(nodes);
  var headIdx = band ? band.start : nodes.length;

  for (var k = 0; k < nodes.length; k++) {
    var n = nodes[k];
    if (n.isLastUser || n.isPrefill) continue;
    if (n.role === 'assistant' || n.role === 'model') continue;
    if (band && k >= band.start && k <= band.end) continue;
    var sc = staticScore(n, nodes.length);
    if (sc < 52) continue;
    if (n.role === 'user' && !hasRuleMarkup(n.text)) continue;
    zones.push({
      score: sc,
      why: 'msg[' + n.index + '](' + n.role + ',' + Math.round(sc) + ')',
      get: (function (msg) { return function () { return getMsgText(msg); }; })(n.msg),
      set: (function (msg) { return function (v) { if (typeof msg.content === 'string') msg.content = v; else msg.content = [{ type: 'text', text: v }]; }; })(n.msg)
    });
  }

  zones.sort(function (a, b) { return b.score - a.score; });
  return zones.slice(0, maxZones);
}

/* ===== 2_refract.js ===== */
/* ============================================================================
 * Anti-Route v6.0 — 2/4 Refraction
 * 三轨微扰（W 空白 / L 语篇词 / A 锚点）+ 预算裁剪 + 块级签名守卫 + 幂等
 * ========================================================================== */

var PROFILE = {
  off:   { tokens: 0,  w: 0, l: 0, a: 0, zones: 0 },
  light: { tokens: 18, w: 3, l: 1, a: 1, zones: 1 },
  mid:   { tokens: 56, w: 6, l: 2, a: 2, zones: 2 }
};
var HARD_TOKEN_CAP = 120;

var ANCHOR_TOPICS = ['rules', 'context', 'section', 'layout', 'style', 'frame', 'notes', 'spec'];
var ANCHOR_KINDS = ['part', 'block', 'node', 'unit', 'seg', 'item'];

/* 语篇连接词：零力度变化，绝不碰模态/否定/义务词 */
var DISCOURSE = [
  [/(^|[，。；：！？\n\s])(此外，|另外，)/g, ['此外，', '另外，']],
  [/(^|[，。；：！？\n\s])(因此，|所以，|因而，)/g, ['因此，', '所以，', '因而，']],
  [/(^|[，。；：！？\n\s])(总之，|总的来说，|简言之，)/g, ['总之，', '总的来说，', '简言之，']],
  [/(^|[，。；：！？\n\s])(例如，|比如，|譬如，)/g, ['例如，', '比如，', '譬如，']],
  [/(^|[，。；：！？\n\s])(同时，|与此同时，)/g, ['同时，', '与此同时，']],
  [/(^|[，。；：！？\n\s])(换言之，|换句话说，)/g, ['换言之，', '换句话说，']],
  [/(\b)(For example,)/g, ['For example,', 'For instance,']],
  [/(\b)(Therefore,)/g, ['Therefore,', 'Thus,', 'Hence,']],
  [/(\b)(However,)/g, ['However,', 'Nevertheless,']]
];

var ANCHOR_STRIP = /(?:^|\n)[ \t]*(?:<!--[ \t]*(?:ctx|ref):[^>]*-->|\[\/\/\]:[ \t]*#[ \t]*\((?:ctx|ref):[^)]*\))[ \t]*(?=\n|$)/g;

var W_STRIP_LIST = /^([ \t]*(?:[-*+]|\d+\.|>))[ \t]{2,}/gm;
var W_STRIP_GAP = /\n[ \t]{1,3}\n/g;

function stripArtifacts(text) {
  if (typeof text !== 'string') return text;

  /* 1) 整行删除锚点（连同它带来的换行），避免首行残留空行 */
  var lines = text.split('\n');
  var kept = [];
  for (var i = 0; i < lines.length; i++) {
    if (/^[ \t]*(?:<!--[ \t]*(?:ctx|ref):[^>]*-->|\[\/\/\]:[ \t]*#[ \t]*\((?:ctx|ref):[^)]*\))[ \t]*$/.test(lines[i])) continue;
    kept.push(lines[i]);
  }
  var out = kept.join('\n');

  /* 2) 还原空白轨：段落间隙与列表标记后的多余空格回到 1 个 */
  out = out.replace(W_STRIP_GAP, '\n\n').replace(W_STRIP_LIST, '$1 ');
  return out;
}

/* ---------------- 随机源（seeded LCG，可复现） ---------------- */

function makeRng(seed) {
  var s = (seed >>> 0) || 0x20261101;
  return function () {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

/* ---------------- 块级签名 ---------------- */

function blockSignature(text) {
  var lines = String(text || '').split('\n');
  var h = [0, 0, 0, 0, 0, 0], li = 0, q = 0, tb = 0, fence = 0;
  for (var i = 0; i < lines.length; i++) {
    var ln = lines[i];
    if (!ln.trim()) continue;
    if (/^[ \t]*(?:<!--|\/\/\]:[ \t]*#)/.test(ln)) continue;
    var mh = /^[ \t]*(#{1,6})[ \t]+\S/.exec(ln);
    if (mh) { h[mh[1].length - 1]++; continue; }
    if (/^[ \t]*(?:[-+*]|\d{1,4}[.)])[ \t]+\S/.test(ln)) { li++; continue; }
    if (/^[ \t]*>/.test(ln)) { q++; continue; }
    if (/^[ \t]*\|.*\|[ \t]*$/.test(ln)) { tb++; continue; }
    if (/^[ \t]*(?:`{3,}|~{3,})/.test(ln)) { fence++; continue; }
  }
  return h.join(',') + '|' + li + '|' + q + '|' + tb + '|' + fence;
}

/* ---------------- W 轨：块级结构空白 ---------------- */

function findWSites(text, spans) {
  var sites = [];
  var patterns = [
    /^(#{1,6})([ \t]{1,2})(?=\S)/gm,
    /^([ \t]{0,3}[-+*])([ \t]{1,2})(?=\S)/gm,
    /^([ \t]{0,3}\d{1,4}[.)])([ \t]{1,2})(?=\S)/gm,
    /^([ \t]{0,3}>)([ \t]{1,2})(?=\S)/gm
  ];
  for (var i = 0; i < patterns.length; i++) {
    var re = new RegExp(patterns[i].source, 'gm');
    var m;
    var guard = 0;
    while ((m = re.exec(text)) !== null && guard++ < 500) {
      var pos = m.index + m[1].length + m[2].length;
      if (isProtected(spans, m.index, pos)) continue;
      sites.push({ pos: pos, kind: 'inline' });
    }
  }
  var gapRe = /([^\n>`~|}])\n(\n)(?=\S)/g;
  var gm;
  var g2 = 0;
  while ((gm = gapRe.exec(text)) !== null && g2++ < 500) {
    var gp = gm.index + 1;
    if (isProtected(spans, gp - 1, gp + 2)) continue;
    sites.push({ pos: gp + 1, kind: 'gap' });
  }
  sites.sort(function (a, b) { return a.pos - b.pos; });
  return sites;
}

function planW(text, spans, max, rng) {
  if (max <= 0) return [];
  var sites = findWSites(text, spans);
  if (!sites.length) return [];
  var picked = [];
  var startIdx = Math.floor(rng() * sites.length);
  for (var step = 0; step < sites.length && picked.length < max; step++) {
    var s = sites[(startIdx + step) % sites.length];
    var clash = false;
    for (var k = 0; k < picked.length; k++) if (Math.abs(picked[k].pos - s.pos) < 36) { clash = true; break; }
    if (clash) continue;
    picked.push(s);
  }
  return picked.map(function (s) {
    return {
      track: 'W', start: s.pos, end: s.pos,
      text: s.kind === 'gap' ? ' ' : ' ',
      weight: 1
    };
  });
}

/* ---------------- L 轨：语篇连接词轮换 ---------------- */

function planL(text, spans, max, rng) {
  if (max <= 0) return [];
  var cands = [];
  for (var i = 0; i < DISCOURSE.length; i++) {
    var re = new RegExp(DISCOURSE[i][0].source, DISCOURSE[i][0].flags);
    var alts = DISCOURSE[i][1];
    var m;
    var guard = 0;
    while ((m = re.exec(text)) !== null && guard++ < 200) {
      var lead = m[1] || '';
      var word = m[2] || '';
      if (!word) continue;
      var start = m.index + lead.length;
      var end = start + word.length;
      if (isProtected(spans, start, end)) continue;
      var pool = [];
      for (var a = 0; a < alts.length; a++) if (alts[a] !== word) pool.push(alts[a]);
      if (!pool.length) continue;
      cands.push({ start: start, end: end, text: pool[Math.floor(rng() * pool.length)] });
    }
  }
  if (!cands.length) return [];
  var picked = [];
  var offset = Math.floor(rng() * cands.length);
  for (var s = 0; s < cands.length && picked.length < max; s++) {
    var c = cands[(offset + s) % cands.length];
    var clash2 = false;
    for (var p = 0; p < picked.length; p++) if (Math.abs(picked[p].start - c.start) < 60) { clash2 = true; break; }
    if (clash2) continue;
    picked.push(c);
  }
  return picked.map(function (c) {
    return { track: 'L', start: c.start, end: c.end, text: c.text, weight: 1 };
  });
}

/* ---------------- A 轨：块级安全锚点 ---------------- */

function buildAnchor(rng, html) {
  var topic = ANCHOR_TOPICS[Math.floor(rng() * ANCHOR_TOPICS.length)];
  var kind = ANCHOR_KINDS[Math.floor(rng() * ANCHOR_KINDS.length)];
  var hex = Math.floor(rng() * 0xffff).toString(16);
  while (hex.length < 4) hex = '0' + hex;
  var tag = rng() < 0.5 ? 'ctx' : 'ref';
  return html ? '<!-- ' + tag + ': ' + topic + ' / ' + kind + ' ' + hex + ' -->'
              : '[//]: # (' + tag + ': ' + topic + ' / ' + kind + ' ' + hex + ')';
}

function isBlockLine(line) {
  var s = String(line || '');
  return /^[ \t]{0,3}(?:[-+*]|\d{1,4}[.)])[ \t]+\S/.test(s) ||
         /^[ \t]{0,3}>/.test(s) ||
         /^[ \t]{0,3}\|.*\|[ \t]*$/.test(s) ||
         /^[ \t]{2,}\S/.test(s);
}

function findAnchorSites(text, spans) {
  var out = [];
  var idx = -1;
  var guard = 0;
  while ((idx = text.indexOf('\n', idx + 1)) !== -1 && guard++ < 4000) {
    if (isProtected(spans, idx, idx + 1)) continue;
    var lineStart = text.lastIndexOf('\n', idx - 1) + 1;
    var prevLine = text.slice(lineStart, idx);
    var nextNl = text.indexOf('\n', idx + 1);
    var nextLine = text.slice(idx + 1, nextNl === -1 ? text.length : nextNl);
    var prevTrim = prevLine.replace(/\s+$/, '');
    if (/[:：<{`\\]$/.test(prevTrim)) continue;
    if (isBlockLine(prevLine) && (isBlockLine(nextLine) || !nextLine.trim())) continue;
    var prevHeading = /^[ \t]{0,3}#{1,6}[ \t]+\S/.test(prevLine);
    var nextHeading = /^[ \t]{0,3}#{1,6}[ \t]+\S/.test(nextLine);
    var blankBoundary = !prevTrim && !isBlockLine(nextLine);
    if (prevHeading || nextHeading || blankBoundary) out.push(idx);
  }
  return out;
}

function planA(text, spans, isHead, max, rng) {
  if (max <= 0) return [];
  var sites = findAnchorSites(text, spans);
  var html = rng() < 0.5;
  var acts = [];
  if (isHead && !isProtected(spans, 0, 1)) {
    var a0 = buildAnchor(rng, html) + '\n';
    acts.push({ track: 'A', start: 0, end: 0, text: a0, weight: estimateTokens(a0) });
    return acts;
  }
  if (!sites.length) return acts;
  var pool = [];
  for (var i = 0; i < sites.length; i++) {
    if (sites[i] >= 4 && sites[i] <= 320) pool.push(sites[i]);
  }
  var target = pool.length ? pool[Math.floor(rng() * pool.length)] : sites[0];
  var ins = '\n' + buildAnchor(rng, !html);
  acts.push({ track: 'A', start: target, end: target, text: ins, weight: estimateTokens(ins) });
  return acts;
}

/* ---------------- 应用（含预算裁剪与签名守卫） ---------------- */

function refractZone(text, opt, rng) {
  var empty = { changed: false, text: text, added: 0, edits: 0, tracks: { W: 0, L: 0, A: 0 } };
  var cleaned = stripArtifacts(text);
  if (typeof cleaned !== 'string' || cleaned.replace(/\s/g, '').length < 40) return empty;

  var spans = collectSpans(cleaned);
  if (spans.length === 1 && spans[0][0] === 0 && spans[0][1] >= cleaned.length) return empty;

  var acts = [];
  if (opt.w > 0) acts = acts.concat(planW(cleaned, spans, opt.w, rng));
  if (opt.l > 0) acts = acts.concat(planL(cleaned, spans, opt.l, rng));
  if (opt.a > 0) acts = acts.concat(planA(cleaned, spans, opt.isHead, opt.a, rng));
  if (!acts.length) return empty;

  var total = 0;
  for (var i = 0; i < acts.length; i++) total += acts[i].weight;
  while (total > opt.budget && acts.length) {
    var dropA = -1, dropL = -1;
    for (var j = 0; j < acts.length; j++) {
      if (acts[j].track === 'A' && dropA < 0) dropA = j;
      if (acts[j].track === 'L' && dropL < 0) dropL = j;
    }
    var di = dropA >= 0 ? dropA : (dropL >= 0 ? dropL : acts.length - 1);
    total -= acts[di].weight;
    acts.splice(di, 1);
  }
  if (!acts.length) return empty;

  acts.sort(function (x, y) { return y.start - x.start || y.end - x.end; });
  var out = cleaned;
  var lastStart = 1e9;
  var applied = 0;
  var tracks = { W: 0, L: 0, A: 0 };
  for (var k = 0; k < acts.length; k++) {
    var act = acts[k];
    if (act.end > lastStart) continue;
    if (act.start > 0 && isProtected(spans, act.start, act.end)) continue;
    out = out.slice(0, act.start) + act.text + out.slice(act.end);
    lastStart = act.start;
    applied++;
    tracks[act.track]++;
  }
  if (!applied || out === cleaned) return empty;

  if (blockSignature(cleaned) !== blockSignature(out)) return empty;

  return { changed: true, text: out, added: Math.max(1, Math.ceil(total)), edits: applied, tracks: tracks };
}

/* ---------------- 请求改写 ---------------- */

function textOfMsg(m) {
  if (!m) return '';
  if (typeof m.content === 'string') return m.content;
  if (Array.isArray(m.content)) {
    for (var i = 0; i < m.content.length; i++) {
      if (m.content[i] && m.content[i].type === 'text') return m.content[i].text || '';
    }
  }
  return '';
}

function setMsgText(m, v) {
  if (typeof m.content === 'string') { m.content = v; return; }
  if (Array.isArray(m.content)) {
    for (var i = 0; i < m.content.length; i++) {
      if (m.content[i] && m.content[i].type === 'text') { m.content[i].text = v; return; }
    }
  }
}

function deriveBase(url, body) {
  try {
    if (body && typeof body.reverse_proxy === 'string' && body.reverse_proxy) return body.reverse_proxy.replace(/\/+$/, '');
    var u = new URL(url, HOST.location ? HOST.location.href : 'http://localhost');
    var path = u.pathname;
    var cut = path.indexOf('/api/backends/chat-completions');
    if (cut >= 0) return u.origin;
    return u.origin;
  } catch (e) { return cfg.dualBase || ''; }
}

function planRequest(rawBody, url, internal) {
  var out = { changed: [], model: '', base: '', body: rawBody };
  var edits = 0, added = 0;
  if (!rawBody) return out;
  var body;
  try { body = JSON.parse(rawBody); } catch (e) { return out; }
  if (!body || typeof body !== 'object' || Array.isArray(body)) return out;

  out.model = String(body.model || body.model_name || '');
  out.base = deriveBase(url, body);
  out.internal = !!internal;

  /* 内部请求（数据库/填表/静默生成）：body 是结构化协议，别名与微扰都可能毁表 */
  if (internal) {
    if (cfg.pin) {
      if (Array.isArray(body.models) && body.models.length) { delete body.models; out.changed.push('删models[]'); }
      if (Object.prototype.hasOwnProperty.call(body, 'allow_fallbacks') && body.allow_fallbacks !== false) {
        body.allow_fallbacks = false; out.changed.push('allow_fallbacks=false');
      }
    }
    if (out.changed.length) out.body = JSON.stringify(body);
    out.edits = 0; out.added = 0;
    return out;
  }

  /* L3 别名钉死：非空时把 model 改写成本值 */
  if (cfg.alias) {
    var wantModel = String(cfg.alias);
    if (body.model && String(body.model) !== wantModel) {
      body.model = wantModel;
      out.changed.push('别名→' + wantModel);
      out.model = wantModel;
    }
  }

  if (cfg.pin) {
    if (Array.isArray(body.models) && body.models.length) { delete body.models; out.changed.push('删models[]'); }
    if (Object.prototype.hasOwnProperty.call(body, 'allow_fallbacks') && body.allow_fallbacks !== false) {
      body.allow_fallbacks = false; out.changed.push('allow_fallbacks=false');
    }
    if (Object.prototype.hasOwnProperty.call(body, 'openrouter_allow_fallbacks') && body.openrouter_allow_fallbacks !== false) {
      body.openrouter_allow_fallbacks = false; out.changed.push('openrouter_allow_fallbacks=false');
    }
    if (Object.prototype.hasOwnProperty.call(body, 'openrouter_use_fallback') && body.openrouter_use_fallback !== false) {
      body.openrouter_use_fallback = false; out.changed.push('openrouter_use_fallback=false');
    }
    if (body.provider && typeof body.provider === 'object' && !Array.isArray(body.provider) &&
        Object.prototype.hasOwnProperty.call(body.provider, 'allow_fallbacks') && body.provider.allow_fallbacks !== false) {
      body.provider.allow_fallbacks = false; out.changed.push('provider.allow_fallbacks=false');
    }
    if (body.route !== undefined && body.route !== null) { delete body.route; out.changed.push('删route'); }
  }

  if (cfg.think === 'high') {
    var hasThink = body.thinking !== undefined || body.thinkingConfig !== undefined || body.reasoning_effort !== undefined;
    if (!hasThink) { body.reasoning_effort = 'high'; out.changed.push('reasoning_effort=high'); }
  }

  if (cfg.refract !== 'off') {
    var prof = PROFILE[cfg.refract] || PROFILE.off;
    var inner = body;
    if (body.request && typeof body.request === 'object' && !Array.isArray(body.request)) inner = body.request;
    var zones = pickZones(inner, '', prof.zones);
    var seedStr = String(out.base || '') + '|' + normModel(out.model) + '|' + saltKey('refract') + '|' + String(cfg.refractSeed || '');
    var seedNum = (cfg.refractMode === 'random') ? (Date.now() ^ 0x5f3759df) : hashStr(seedStr);
    var rng = makeRng(seedNum >>> 0);
    var touched = 0, tk = { W: 0, L: 0, A: 0 };
    var budget = Math.min(prof.tokens, HARD_TOKEN_CAP);
    for (var i = 0; i < zones.length; i++) {
      if (budget <= 0) break;
      var before = zones[i].get();
      var res = refractZone(before, {
        w: prof.w, l: prof.l, a: prof.a, isHead: i === 0, budget: budget
      }, rng);
      if (!res.changed) continue;
      zones[i].set(res.text);
      touched++;
      added += res.added;
      edits += res.edits;
      budget -= res.added;
      tk.W += res.tracks.W; tk.L += res.tracks.L; tk.A += res.tracks.A;
    }
    if (touched > 0) {
      out.changed.push('微扰' + touched + '区/W' + tk.W + '·L' + tk.L + '·A' + tk.A + '/+' + added + 'tok');
    }
  }

  /* v8.31 叙述层：防全知 / 去媚。
     放在微扰之后（否则每轮措辞会被空格和连接词扰动，同一份文案两种说法）、
     破甲之前（破甲的「直接写」尾巴必须压在最末尾，那是最强位置）。
     注：这里改的是 JSON.parse 出来的副本，聊天记录一个字节都不动。
     关档时也照样调一次：它的另一个职责是「把上一轮留下的块剥干净」，
     真靠开关判断跳过，遇到带残留块的请求体就永远剥不掉了。整个调用只是两次 indexOf，可忽略。 */
  try {
    var nch = narrApply(body);
    for (var nz = 0; nz < nch.length; nz++) out.changed.push(nch[nz]);
  } catch (eNarr) {}

  /* v0.76 反 OOC：紧跟叙述层。
     有 setExtensionPrompt 通道时只写通道（oocApply 返回 true），
     请求体里只保留「剥掉上一轮残留块」这一个动作——两边都塞会重复注入两遍。
     没有通道（老版本酒馆 / 测试环境）才回落到贴末条 user 消息尾部。
     关档时也照调一次：它的另一个职责是把上一轮留下的块剥干净。 */
  try {
    if (typeof oocApply === 'function' && !oocApply()) {
      var och = oocBodyPatch(body);
      for (var oz = 0; oz < och.length; oz++) out.changed.push(och[oz]);
    }
  } catch (eOoc) {}

  /* v0.7 抗截断（事前注入）：叙述之后、破甲之前。
     顺序：微扰 → 叙述 → 截断 → 破甲 → 序列化；破甲的「直接写」必须压在最末尾。
     关档 / 预设已经自带同类指令时 truncApply 返回 false，这里什么都不做，请求一个字节都不变。
     ★ 必须把改动报给 out.changed：下面只在这个数组非空时才 JSON.stringify 回去，
       裸调一次会让注入的块留在内存里、白写一轮。 */
  try {
    var tmsgs = (body.request && Array.isArray(body.request.messages)) ? body.request.messages : body.messages;
    if (typeof truncApply === 'function' && truncApply(tmsgs)) {
      out.changed.push('截断:' + truncLabel(cfg ? cfg.trunc : TRUNC_LIGHT));
    }
  } catch (eTrunc) {}

  /* v7.1 破甲（强力档）：放在微扰之后、序列化之前——放前面会被微扰再扰动一遍 */
  if (cfg.enabled && cfg.jail === 'strong') {
    try {
      var jch = jailPatchBody(body);
      for (var jz = 0; jz < jch.length; jz++) out.changed.push(jch[jz]);
    } catch (eJail) {}
  }

  /* v7.4：到底钉住了几个 + 有没有别的护盾在同一份请求里注入 */
  try { out.audit = lockAudit(body); } catch (eA) {}
  try { out.foreign = foreignShield(body); } catch (eF) {}

  /* 关键：只要动过 body，就必须序列化回去；否则钉参数只改了内存对象 */
  if (out.changed.length) out.body = JSON.stringify(body);

  out.edits = edits;
  out.added = added;
  return out;
}

/* ===== 12_narr.js ===== */
/* 12_narr.js — v8.31 叙述层：防全知 / 去媚，各三档
 *
 * 为什么不再用酒馆正则：
 *   原正则 `^(.+)$` 里的 `.` 不跨行、JS 的 `$` 也不吃结尾换行 —— 用户输入一多行就静默失效；
 *   两条同时开还会互相把对方的输出吃掉（一条输出 13 行，另一条的 ^(.+)$ 一行都匹配不上）。
 *   这里改成直接改请求体：多行、嵌套、幂等、去重全部由代码保证，错了也不会静默。
 *
 * 注入位置：planRequest 里「微扰之后、破甲之前」。
 *   - 微扰之后：叙述文本不能被空格/连接词扰动，否则每轮措辞都不一样；
 *   - 破甲之前：破甲的「直接写」尾巴要压在最末尾，那是最强位置。
 *
 * 三条不变量：
 *   1) 只改请求体里的那份副本，聊天记录一个字都不动（所以重发/刷新不会累积）；
 *   2) 幂等：注入前先剥掉上一次的块，注入 N 次和注入 1 次结果完全一样；
 *   3) 失败安全：任何一步抛错都原样返回，绝不让叙述层把请求搞坏。
 */

var NARR_TAG = 'AR-NAR';
var NARR_VER = '8.31';
var NARR_OPEN = '〔AR-NAR ' + NARR_VER + '〕';
var NARR_CLOSE = '〔/AR-NAR〕';
var NARR_TIERS = ['off', 'lite', 'full'];

/* ---------------- 文案 ----------------
