/* ---------------- 状态 ---------------- */

function narrPick(v) {
  var s = String(v == null ? '' : v);
  for (var i = 0; i < NARR_TIERS.length; i++) if (NARR_TIERS[i] === s) return s;
  return 'off';
}
function narrTag(v) {
  var s = narrPick(v);
  return s === 'off' ? '关' : (s === 'lite' ? '轻' : '强');
}
function narrNext(v) {
  var s = narrPick(v);
  return s === 'off' ? 'lite' : (s === 'lite' ? 'full' : 'off');
}
/* 防全知要开的时候，要不要先说明一次。
   它是唯一会「禁止写内心话、禁止替角色做决定」的开关，想抢话的人必须先知道；
   关掉提醒后就一直闭嘴，不再拦。 */
function narrTipNeeded(next, tip) {
  var n = narrPick(next);
  if (n === 'off') return false;
  return String(tip == null ? 'on' : tip) !== 'off';
}

/* 名字：能拿到 ST 的 name1 就换成真名，拿不到就退回「你」。
   注意别把尖括号留在提示里 —— 有些渠道会把 <user> 当成未知标签吞掉。 */
function narrUserName() {
  try {
    var c = stCtx();
    if (!c) return '';
    var n = String(c.name1 == null ? '' : c.name1).trim();
    n = n.replace(/[〔〕【】\[\]<>]/g, '').slice(0, 24).trim();
    return n;
  } catch (e) { return ''; }
}

function narrFill(t) {
  var s = String(t == null ? '' : t);
  if (s.indexOf('<user>') < 0) return s;
  var n = narrUserName() || '你';
  return s.split('<user>').join(n);
}

/* 拼出这一轮要注入的整块；两个都关时返回空串 */
function narrBody() {
  var parts = [];
  var charm = NARR_CHARM[narrPick(cfg && cfg.charm)] || '';
  var know = NARR_KNOW[narrPick(cfg && cfg.know)] || '';
  if (charm) parts.push(narrFill(charm));
  if (know) parts.push(narrFill(know));      /* 防全知在内层：离生成位置最近 */
  if (!parts.length) return '';
  return NARR_OPEN + '\n' + parts.join('\n') + '\n' + NARR_CLOSE;
}

function narrLabel() {
  var a = (cfg && cfg.know !== 'off') ? ('防全知' + narrTag(cfg.know)) : '';
  var b = (cfg && cfg.charm !== 'off') ? ('去媚' + narrTag(cfg.charm)) : '';
  if (a && b) return a + '+' + b;
  return a || b || '关';
}

/* 粗估 token：中文约 0.7 tok/字，只用来给面板一个量级，不当计费依据 */
function narrTokens() {
  var b = narrBody();
  if (!b) return 0;
  return Math.round(b.length * 0.7);
}

/* 剥掉上一次注入的块。找不到标记就原样返回 —— 绝不做「猜着删」。 */
function narrStripOnce(s) {
  var t = String(s == null ? '' : s);
  var i = t.indexOf('〔' + NARR_TAG);
  if (i < 0) return t;
  var j = t.indexOf(NARR_CLOSE, i);
  if (j < 0) return t;
  j += NARR_CLOSE.length;
  var head = t.slice(0, i);
  var tail = t.slice(j);
  /* 连带吃掉两边的空白，否则每轮重注入都会多一行空行，越滚越长 */
  head = head.replace(/[ \t]+$/, '');
  tail = tail.replace(/^[ \t\r\n]+/, '');
  if (!tail) return head.replace(/[\s]+$/, '');
  return head + (head ? '\n\n' : '') + tail;
}

/* 历史遗留可能留了两块（旧版注入过 + 这版又注入），一次剥一块不够。
   上限 8 次只是防呆，正常一轮就结束。 */
function narrStrip(s) {
  var t = String(s == null ? '' : s);
  for (var k = 0; k < 8; k++) {
    var n = narrStripOnce(t);
    if (n === t) break;
    t = n;
  }
  return t;
}

/* 真正的注入：只改传入的 body 副本 */
function narrApply(body) {
  var out = [];
  if (!body || typeof body !== 'object') return out;
  var msgs = (body.request && typeof body.request === 'object' && Array.isArray(body.request.messages))
    ? body.request.messages
    : (Array.isArray(body.messages) ? body.messages : null);
  if (!msgs || !msgs.length) return out;

  /* 末尾向前找第一条 user：破甲的 /continue 轮里，末条是 assistant 占位 */
  var idx = -1;
  for (var i = msgs.length - 1; i >= 0; i--) {
    var m = msgs[i];
    if (m && String(m.role || '') === 'user') { idx = i; break; }
  }
  if (idx < 0) return out;

  var m2 = msgs[idx];
  var old = String(textOfMsg(m2) || '');
  var base = narrStrip(old);
  var block = narrBody();

  if (!block) {
    if (base !== old) { setMsgText(m2, base); out.push('叙述:清掉'); }
    return out;
  }

  var sep = '';
  if (base) sep = /\n$/.test(base) ? '\n' : '\n\n';
  var next = base + sep + block;
  if (next !== old) {
    setMsgText(m2, next);
    out.push('叙述:' + narrLabel());
  }
  return out;
}

/* ===== 15_ooc.js ===== */
/* 15_ooc.js — v0.76 反 OOC：点名 / 反模板 / 变更门槛 / 口吻一致
 *
 * 四件事，四个开关，各管各的：
 *   点名      —— 先认出这一轮在场的是谁，再让他们各自对照世界书；
 *   反模板    —— 同一类情绪别用现成的动作包（眼底闪过、嘴角勾起…）；
 *   变更门槛  —— 态度 / 关系 / 立场变了，要指得出是哪件事改的；
 *   口吻一致  —— 说话方式、称呼、口癖跟前文一致（换人检验）。
 *
 * 三条不变量（与 12_narr.js 同）：
 *   1) 预设只读：这里只决定自己注不注，从不删改请求体里预设的任何内容；
 *   2) 幂等：注入前先剥掉上一次的块，注一次和注十次结果完全一样；
 *   3) 失败安全：任何一步抛错都退化成「什么都不注」，绝不让它弄坏正常请求。
 *
 * 注入通道：优先酒馆自己的扩展提示位（setExtensionPrompt，IN_CHAT / depth 4）；
 * 宿主没有这个方法时回落成「贴末条 user 消息尾部」，与叙述层同一位置。
 *   ★ 扩展提示位是宿主持久保存的：写进去之后由宿主自己在下一轮拼提示时带上，
 *     所以这条路径不改请求体、也不会和回落路径同时生效（oocApply 返回 true 时
 *     planRequest 不会再调 oocBodyPatch）。
 *
 * 世界书：只读 ctx.characters[this_chid].data.extensions.world → loadWorldInfo(book)。
 *   loadWorldInfo 在部分版本上是 Promise，这里只吃同步返回值；拿到 Promise 就当
 *   拿不到（宁可这一轮不点名，也不把请求挂死）。
 */

var OOC_TAG = '〔AR-OOC 1.0〕';
var OOC_KEY = 'ar6.ooc';
var OOC_ITEMS = ['roll', 'tpl', 'chg', 'voice'];
var OOC_CFGKEY = { roll: 'oocRoll', tpl: 'oocTpl', chg: 'oocChg', voice: 'oocVoice' };
var OOC_LABEL = { roll: '点名', tpl: '反模板', chg: '变更门槛', voice: '口吻一致' };

/* ---------------- 文案 ----------------
   四段各自成块，各自带同一个头（OOC_TAG），中间空一行。
   面板预览与注入用的是同一份文案，不许只改一边：
   改一个字，用户面板上看到的和这里给的就不是同一份东西了。
   {{user}} 原样保留，输出前由 oocFill() 换成真名（拿不到就换「你」）。 */
var OOC_SEG_TPL = OOC_TAG + '\n' +
  '同一类情绪，不要用现成的动作包打发——眼底闪过、嘴角勾起、喉结滚动、\n' +
  '呼吸一滞、身子一僵，这类动作谁都能做，写了等于没写。\n' +
  '\n' +
  '不要用一句话概括一个人的全部性格，也不要让他只当「那个温柔的人」。\n' +
  '\n' +
  '他做的动作，得是这个人做得出来的动作。';

var OOC_SEG_CHG = OOC_TAG + '\n' +
  '一个人对另一个人的态度、关系、立场变了，要指得出是哪件事改变的、中间经过什么。\n' +
  '\n' +
  '说不出缘由的变化，不要写。';

var OOC_SEG_VOICE = OOC_TAG + '\n' +
  '他的说话方式、称呼、口癖、句子长短，跟前文保持一致。\n' +
  '\n' +
  '检验方法：把这句话换给另一个人说，如果照样成立，那就是写错了，重写。';

/* 点名：名单由调用方拼，「、」连接 + 「。」 */
function oocRollSeg(names) {
  var list = String((names || []).join('、')).replace(/[、\s]+$/, '');
  return OOC_TAG + '\n' +
    '本轮涉及的角色：' + list + '。\n' +
    '\n' +
    '动笔前，逐一对照世界书里他们各自的条目——\n' +
    '他怎么说话、对{{user}}是什么态度、什么事他不会做。\n' +
    '\n' +
    '世界书写了的，以世界书为准；世界书没写的，按前文已经写过的演，不要改。';
}

/* ---------------- 配置 ---------------- */

function oocFlag(v, dflt) {
  if (v === undefined || v === null) return dflt;
  return !!v;
}

/* 总闸关 → 返回 null（调用方一律当「什么都不做」）。
   注意：读的是 cfg 里的存值；CFG_DEFAULT 的默认值是 off，迁移不重跑。 */
function oocCfg() {
  var c = (cfg && typeof cfg === 'object') ? cfg : null;
  if (!c) return null;
  if (String(c.ooc == null ? 'off' : c.ooc) !== 'on') return null;
  return {
    roll: oocFlag(c.oocRoll, true),
    tpl: oocFlag(c.oocTpl, true),
    chg: oocFlag(c.oocChg, false),
    voice: oocFlag(c.oocVoice, true)
  };
}

/* 单项是否开着（面板渲染用；总闸关时一律当关） */
function oocOnOf(item) {
  var c = oocCfg();
  if (!c) return false;
  return !!c[item];
}

/* ---------------- 宿主上下文（老 ST 可能什么都没有） ---------------- */

function oocCtx() {
  try {
    if (typeof stCtx === 'function') {
      var c = stCtx();
      if (c) return c;
    }
  } catch (e0) {}
  try {
    var st = (typeof HOST !== 'undefined' && HOST) ? HOST.SillyTavern : null;
    if (st && typeof st.getContext === 'function') return st.getContext();
  } catch (e1) {}
  return null;
}

/* 这个角色绑的世界书名；没绑返回空串 */
function oocBook() {
  try {
    var c = oocCtx();
    if (!c) return '';
    var list = c.characters;
    var id = c.this_chid;
    if (list == null || id == null || id === '') return '';
    var n = +id;
    if (!isFinite(n) || n < 0) return '';
    var ch = list[n];
    if (!ch) return '';
    var d = ch.data;
    var ext = d && d.extensions;
    var w = ext && ext.world;
    return String(w == null ? '' : w).trim();
  } catch (e) { return ''; }
}

/* 世界书条目 → 人物名单。只认两种写法：
   P1  comment 带 [角色] / [人物] / [NPC] … 前缀；
   P2  comment 本身就是 2~6 字的纯名字，且每个 key 也都是 2~6 字纯名字。 */
var OOC_NAME_RE = /^[\u4e00-\u9fa5A-Za-z·]{2,6}$/;
var OOC_P1_RE = /^\[(角色|人物|NPC|npc|char|Char)\]\s*/;

function oocTrim(s) {
  return String(s == null ? '' : s).replace(/^[\s\u3000]+|[\s\u3000]+$/g, '');
}

function oocKeys(e) {
  var out = [];
  if (!e || !Array.isArray(e.key)) return out;
  for (var i = 0; i < e.key.length; i++) {
    var k = oocTrim(e.key[i]);
    if (!k) continue;
    if (out.indexOf(k) < 0) out.push(k);
  }
  return out;
}

/* 世界书数据的同步缓存。
   新版酒馆的 ctx.loadWorldInfo 返回 Promise，同步路径拿不到；这里把 Promise
   的结果回填进来，下一次渲染 / 下一轮请求就能用（TTL 30 秒，改完世界书不用刷新）。
   key 是书名；只缓存成功解析过的整本数据。 */
var OOC_BOOK_CACHE = {};
var OOC_BOOK_WAIT = {};
var OOC_BOOK_TTL = 30000;

function oocBookCached(book, c) {
  var hit = OOC_BOOK_CACHE[book];
  if (hit) {
    if ((Date.now() - hit.at) < OOC_BOOK_TTL) return hit.data;
    delete OOC_BOOK_CACHE[book];
  }
  var data;
  try { data = c.loadWorldInfo(book); } catch (e0) { return null; }
  if (data && typeof data.then === 'function') {
    /* Promise 不认识，也没法在这里 await —— 挂一次 then 回填，这一轮先当拿不到 */
    if (!OOC_BOOK_WAIT[book]) {
      OOC_BOOK_WAIT[book] = 1;
      try {
        data.then(function (d) {
          delete OOC_BOOK_WAIT[book];
          if (d && typeof d === 'object') OOC_BOOK_CACHE[book] = { data: d, at: Date.now() };
        }, function () { delete OOC_BOOK_WAIT[book]; });
      } catch (e1) { delete OOC_BOOK_WAIT[book]; }
    }
    return null;
  }
  if (!data || typeof data !== 'object') return null;
  return data;
}

function oocPeople(bookName) {
  var out = [];
  var book = oocTrim(bookName);
  if (!book) return out;
  var c = oocCtx();
  if (!c || typeof c.loadWorldInfo !== 'function') return out;
  var data = oocBookCached(book, c);
  if (!data) return out;
  var ent = data.entries;
  if (!ent || typeof ent !== 'object') return out;

  var seen = {};
  var i, e, cm, nm, keys, m;
  var uids = [];
  if (Array.isArray(ent)) {
    for (i = 0; i < ent.length; i++) uids.push(i);
  } else {
    for (var k in ent) if (Object.prototype.hasOwnProperty.call(ent, k)) uids.push(k);
  }

  for (i = 0; i < uids.length && out.length < 40; i++) {
    e = ent[uids[i]];
    if (!e || typeof e !== 'object') continue;
    if (e.disable === true) continue;
    cm = oocTrim(e.comment);
    if (!cm) continue;
    nm = '';
    keys = oocKeys(e);
    m = OOC_P1_RE.exec(cm);
    if (m) {
      nm = oocTrim(cm.slice(m[0].length));
      if (!nm) continue;
    } else if (OOC_NAME_RE.test(cm) && keys.length) {
      var ok = true;
      for (var j = 0; j < keys.length; j++) {
        if (!OOC_NAME_RE.test(keys[j])) { ok = false; break; }
      }
      if (!ok) continue;
      nm = cm;
    } else {
      continue;
    }
    if (seen[nm]) continue;
    seen[nm] = 1;
    out.push({ name: nm, keys: keys });
  }
  return out;
}

/* 在场：按 key 在最近两条消息里出现几次排序，取前 6。
   次数相同按世界书里的先后，保证同一段对话里名单稳定。 */
function oocPresent(people, text) {
  var out = [];
  if (!people || !people.length) return out;
  var t = String(text == null ? '' : text);
  if (!t) return out;
  var hit = [];
  for (var i = 0; i < people.length; i++) {
    var p = people[i];
    if (!p) continue;
    var ks = p.keys || [];
    var n = 0;
    for (var j = 0; j < ks.length; j++) {
      var k = String(ks[j] == null ? '' : ks[j]);
      if (!k) continue;
      var at = t.indexOf(k);
      while (at >= 0) {
        n++;
        at = t.indexOf(k, at + k.length);
        if (n > 99) break;
      }
    }
    if (n > 0) hit.push({ name: String(p.name || ''), n: n, i: i });
  }
  if (!hit.length) return out;
  hit.sort(function (a, b) { return (b.n - a.n) || (a.i - b.i); });
  for (var q = 0; q < hit.length && q < 6; q++) out.push(hit[q].name);
  return out;
}

/* 最近两条消息的正文；ctx.chat 不可用时返回空串 */
function oocRecent() {
  try {
    var c = oocCtx();
    if (!c) return '';
    var ch = c.chat;
    if (!ch || !ch.length) return '';
    var from = ch.length - 2;
    if (from < 0) from = 0;
    var parts = [];
    for (var i = from; i < ch.length; i++) {
      var m = ch[i];
      if (!m) continue;
      parts.push(String(m.mes == null ? '' : m.mes));
    }
    return parts.join('\n');
  } catch (e) { return ''; }
}

/* ---------------- 冲突选项（只在本会话内，不落配置） ----------------
   'script' = 用我们的；'preset' = 听预设的（这一段就不注了）。 */
var OOC_CHOICE = {};

function oocChoice(item) {
  var v = OOC_CHOICE[String(item == null ? '' : item)];
  return (v === 'script' || v === 'preset') ? v : '';
}

function oocSetChoice(item, v) {
  var k = String(item == null ? '' : item);
  if (OOC_ITEMS.indexOf(k) < 0) return '';
  if (v !== 'script' && v !== 'preset') { delete OOC_CHOICE[k]; return ''; }
  OOC_CHOICE[k] = v;
  return v;
}

function oocResetChoice() {
  for (var i = 0; i < OOC_ITEMS.length; i++) delete OOC_CHOICE[OOC_ITEMS[i]];
}

/* ---------------- 拼接 ---------------- */

/* {{user}} → 真名（拿不到就用「你」）。这里不碰尖括号，文案里也没有 <user>。 */
function oocFill(t) {
  var s = String(t == null ? '' : t);
  if (s.indexOf('{{user}}') < 0) return s;
  var n = '';
  try { if (typeof narrUserName === 'function') n = narrUserName(); } catch (e) {}
  return s.split('{{user}}').join(n || '你');
}

/* 这一轮要注的整块；总闸关 / 四项全关时返回空串 */
function oocText() {
  var c = oocCfg();
  if (!c) return '';
  var parts = [];

  /* 先算「这一轮提到了谁」。世界书里一个人物都认不出来时不做拦截
     （可能是没绑世界书，不能因此把功能关掉）；但只要认得出人物、
     而最近两条消息里一个都没提到，就整块不注——没人在场的时候
     跟模型讲「别写 OOC」只是噪音，还白花 token。 */
  var names = [];
  var known = 0;
  try {
    var book = oocBook();
    if (book) {
      var people = oocPeople(book);
      known = people.length;
      if (known) names = oocPresent(people, oocRecent());
    }
  } catch (e0) { names = []; known = 0; }
  if (known > 0 && !names.length) return '';

  /* 1) 点名：认不出人就不注这一段（写「本轮涉及的角色：。」没有意义） */
  if (c.roll && oocChoice('roll') !== 'preset') {
    if (names.length) parts.push(oocFill(oocRollSeg(names)));
  }

  /* 2~4) 反模板 → 变更门槛 → 口吻一致（顺序固定，别按开关顺序拼） */
  if (c.tpl && oocChoice('tpl') !== 'preset') parts.push(oocFill(OOC_SEG_TPL));
  if (c.chg && oocChoice('chg') !== 'preset') parts.push(oocFill(OOC_SEG_CHG));
  if (c.voice && oocChoice('voice') !== 'preset') parts.push(oocFill(OOC_SEG_VOICE));

  return parts.join('\n\n');
}

/* 粗估 token（中文约 0.7 tok/字），只给面板一个量级 */
function oocTokens() {
  var t = '';
  try { t = oocText(); } catch (e) { t = ''; }
  return t ? Math.round(t.length * 0.7) : 0;
}

function oocLabel() {
  var c = oocCfg();
  if (!c) return '关';
  var out = [];
  for (var i = 0; i < OOC_ITEMS.length; i++) {
    var k = OOC_ITEMS[i];
    if (!c[k] || oocChoice(k) === 'preset') continue;
    out.push(OOC_LABEL[k]);
  }
  return out.length ? out.join('+') : '关';
}

/* ---------------- 注入 ---------------- */

/* 剥掉上一次注入的块。
   我们的块永远是整块贴在尾部（四段各带同一个头，块内没有别人的东西），
   所以从第一个标记砍到结尾即可；剥完把尾部空白收掉，免得每轮多一行空行。 */
function oocStrip(s) {
  var t = String(s == null ? '' : s);
  var i = t.indexOf(OOC_TAG);
  if (i < 0) return t;
  return t.slice(0, i).replace(/[ \t\r\n]+$/, '');
}

/* 扩展提示位通道：拿得到 ctx 且它真的有 setExtensionPrompt 才算 */
function oocChannel() {
  try {
    var c = oocCtx();
    if (c && typeof c.setExtensionPrompt === 'function') return c;
  } catch (e) {}
  return null;
}

/* 写扩展提示位。true = 这一次走的就是这条通道；false = 交给 oocBodyPatch 回落。
   文本为空时写空串，等于把上一轮留下的块清掉（不然关掉总闸之后它还在）。 */
function oocApply() {
  var text = '';
  try { text = oocText(); } catch (e0) { text = ''; }
  var c = oocChannel();
  if (!c) return false;
  try {
    c.setExtensionPrompt(OOC_KEY, text, 1, 4, false, 0);
    return true;
  } catch (e1) { return false; }
}

/* 回落通道：贴到最后一条 role==='user' 的 content 尾部（与 narrApply 同一位置）。
   只改传进来的 body 副本，聊天记录一个字节都不动。
   返回改动描述数组，调用方必须 push 到 out.changed，否则不会序列化。 */
function oocBodyPatch(body) {
  var out = [];
  if (!body || typeof body !== 'object') return out;
  var msgs = (body.request && typeof body.request === 'object' && Array.isArray(body.request.messages))
    ? body.request.messages
    : (Array.isArray(body.messages) ? body.messages : null);
  if (!msgs || !msgs.length) return out;

  var idx = -1;
  for (var i = msgs.length - 1; i >= 0; i--) {
    var m = msgs[i];
    if (m && String(m.role || '') === 'user') { idx = i; break; }
  }
  if (idx < 0) return out;

  var m2 = msgs[idx];
  var old = '';
  try { old = String(textOfMsg(m2) || ''); } catch (e0) { old = ''; }
  var base = oocStrip(old);
  var block = '';
  try { block = oocText(); } catch (e1) { block = ''; }

  if (!block) {
    if (base !== old) {
      try { setMsgText(m2, base); } catch (e2) { return out; }
      out.push('反OOC:清掉');
    }
    return out;
  }

  var sep = '';
  if (base) sep = /\n$/.test(base) ? '\n' : '\n\n';
  var next = base + sep + block;
  if (next !== old) {
    try { setMsgText(m2, next); } catch (e3) { return out; }
    out.push('反OOC:' + oocLabel());
  }
  return out;
}

/* ---------------- 预设签名：预设是不是已经自带同类指令 ----------------
   §1 的四组关键词，只认有没有，不认强弱。扫的是「真正启用」的条目：
   prompt_order[].order[] 里 enabled===true 的，用 .identifier 映射回 prompts[i]，
   映射不上就按同一位置的索引对齐（老预设没有 identifier）。 */
var OOC_SIG_WORDS = {
  tpl: ['模板', '脸谱', '刻板', '桥段', 'stereotyp', 'trope', 'cliché'],
  chg: ['变化', '缘由', '转变', '动机', 'event', 'process'],
  voice: ['口吻', '说话方式', '口头禅', 'voice', 'tone', 'speech pattern'],
  roll: ['世界书', '人设', '角色设定', 'lorebook', 'persona']
};

function oocHitWord(words, text) {
  var s = String(text == null ? '' : text).toLowerCase();
  for (var i = 0; i < words.length; i++) {
    var w = String(words[i] || '').toLowerCase();
    if (w && s.indexOf(w) >= 0) return w;
  }
  return '';
}

function oocSigName(p, text) {
  var nm = oocTrim(p && (p.name || p.identifier));
  var sn = String(text == null ? '' : text).replace(/\s+/g, ' ').replace(/^[\s\u3000]+/, '').slice(0, 20);
  if (nm && sn) return nm + ' · ' + sn;
  return nm || sn;
}

/* 当前预设对象；拿不到就返回 null（拿不到 = 不弹窗，不会误判） */
function oocPreset() {
  try {
    var c = oocCtx();
    if (c) {
      if (c.preset && Array.isArray(c.preset.prompt_order)) return c.preset;
      if (c.presetManager && Array.isArray(c.presetManager.prompt_order)) return c.presetManager;
      if (typeof c.getPresetManager === 'function') {
        var pm = c.getPresetManager();
        if (pm && Array.isArray(pm.prompt_order)) return pm;
      }
    }
  } catch (e0) {}
  try {
    var st = (typeof HOST !== 'undefined' && HOST) ? HOST.SillyTavern : null;
    if (st && typeof st.getPresetManager === 'function') {
      var pm2 = st.getPresetManager();
      if (pm2 && Array.isArray(pm2.prompt_order)) return pm2;
    }
  } catch (e1) {}
  return null;
}

function oocMatchPrompt(prompts, o, j) {
  var id = (o && o.identifier != null) ? String(o.identifier) : '';
  if (id) {
    for (var i = 0; i < prompts.length; i++) {
      var p = prompts[i];
      if (p && String(p.identifier == null ? '' : p.identifier) === id) return p;
    }
  }
  var q = prompts[j];
  return (q && typeof q === 'object') ? q : null;
}

function oocSig(preset) {
  var sig = { tpl: false, chg: false, voice: false, roll: false, hits: {} };
  var p = null;
  try { p = preset || oocPreset(); } catch (e0) { p = null; }
  if (!p || typeof p !== 'object') return sig;
  var prompts = Array.isArray(p.prompts) ? p.prompts : [];
  var orders = Array.isArray(p.prompt_order) ? p.prompt_order : [];
  if (!orders.length) return sig;

  var used = {};
  for (var i = 0; i < orders.length; i++) {
    var ord = orders[i] && orders[i].order;
    if (!Array.isArray(ord)) continue;
    for (var j = 0; j < ord.length; j++) {
      var o = ord[j];
      if (!o || o.enabled !== true) continue;      /* 只认真正启用的条目 */
      var pr = oocMatchPrompt(prompts, o, j);
      if (!pr) continue;
      var mk = String(pr.identifier == null ? j : pr.identifier);
      if (used[mk]) continue;
      used[mk] = 1;
      var text = String(pr.content == null ? '' : pr.content);
      if (!text) continue;
      for (var t = 0; t < OOC_ITEMS.length; t++) {
        var k = OOC_ITEMS[t];
        if (sig[k]) continue;
        if (!oocHitWord(OOC_SIG_WORDS[k], text)) continue;
        sig[k] = true;
        sig.hits[k] = oocSigName(pr, text);
      }
    }
  }
  return sig;
}

/* 需要问的项：开着 + 预设也管了 + 还没定过。
   一旦用户勾了「以后都按这个来」（cfg.oocPolicy），就直接按全局策略落定，不再问。 */
function oocAsk() {
  var out = [];
  var c = oocCfg();
  if (!c) return out;
  var pol = String((cfg && cfg.oocPolicy) || '');
  if (pol !== 'script' && pol !== 'preset') pol = '';
  var sig = null;
  try { sig = oocSig(); } catch (e0) { return out; }
  for (var i = 0; i < OOC_ITEMS.length; i++) {
    var k = OOC_ITEMS[i];
    if (!c[k]) continue;
    if (!sig[k]) continue;
    if (oocChoice(k)) continue;
    if (pol) { OOC_CHOICE[k] = pol; continue; }
    out.push(k);
  }
  return out;
}

/* ---------------- 面板 ---------------- */

/* 子 chip 上的字：开 / 关 / 听预设（听预设时 chip 本身置灰） */
var OOC_ICON = { roll: '🧩', tpl: '🚫', chg: '🔒', voice: '🗣' };

function oocChipLabel(item) {
  var k = String(item == null ? '' : item);
  var nm = OOC_LABEL[k] || k;
  var ic = OOC_ICON[k] || '🎛';
  if (oocChoice(k) === 'preset') return ic + ' ' + nm + ':听预设';
  return ic + ' ' + nm + ':' + (oocOnOf(k) ? '开' : '关');
}

/* 状态行：世界书 + 认出来几个人。只读，不改任何状态。 */
function oocStatusLine() {
  try {
    var book = oocBook();
    if (!book) return '这个角色没绑世界书';
    var people = oocPeople(book);
    if (!people.length) return '世界书：' + book + ' · 没认出人物条目';
    return '世界书：' + book + ' · 识别到 ' + people.length + ' 个人物';
  } catch (e) { return ''; }
}

/* ===== 5_route.js ===== */
/* ============================================================================
 * Anti-Route v7 — 5/6 Route
 * 渠道可验性门禁 / 别名钉死 / 瘦身报告 / 路由率 KPI / 档位可观测性检查
 * 原则：全部是「旁路探针 + 展示」，不在生成路径上加任何计算
 * ========================================================================== */

var CH_KEY = 'ar7.ch';
var ALIAS_CACHE = null;

/* ---------------- 渠道状态 ---------------- */

function chKeyOf(base, key) {
  return String(hashStr(String(base || '').replace(/\/+$/, '') + '|' + String(key || '')));
}

/* 当前渠道基址：优先面板里填的，其次用上一轮请求实际发往的 base */
function curBase() {
  var b = String(cfg.dualBase || lastReqBase() || '').replace(/\/+$/, '');
  if (b) return b;
  try { if (lastReq && lastReq.base) return String(lastReq.base).replace(/\/+$/, ''); } catch (e) {}
  return '';
}

function readChAll() {
  try {
    var o = JSON.parse(HOST.localStorage.getItem(CH_KEY) || '{}');
    return (o && typeof o === 'object') ? o : {};
  } catch (e) { return {}; }
}

function writeChAll(o) {
  try { HOST.localStorage.setItem(CH_KEY, JSON.stringify(o)); } catch (e) {}
}

function chState() {
  var b = curBase();
  if (!b) return { echoes: null, at: 0, base: '' };
  var all = readChAll();
  var st = all[chKeyOf(b, cfg.dualKey || '')];
  if (!st || typeof st !== 'object') return { echoes: null, at: 0, base: b };
  st.base = b;
  return st;
}

function setChState(st) {
  var b = curBase();
  if (!b) return false;
  var all = readChAll();
  var next = { echoes: st.echoes, at: nowMs(), base: b, note: st.note || '' };
  all[chKeyOf(b, cfg.dualKey || '')] = next;
  writeChAll(all);
  return true;
}

/* 可验性标签：true=回显不可验 / false=可验 / null=未验 */
function verifiableLabel() {
  var st = chState();
  if (st.echoes === true) return '不可验';
  if (st.echoes === false) return '可验';
  return '未验';
}

function verifiableCode() {
  var st = chState();
  if (st.echoes === true) return 'no';
  if (st.echoes === false) return 'yes';
  return 'unknown';
}

/* ---------------- 最小探针 ---------------- */

function probeFetchFn() {
  try { if (typeof probeFetch === 'function' && probeFetch) return probeFetch; } catch (e) {}
  try { return HOST.fetch; } catch (e) { return null; }
}

function probeOnce(url, bodyObj, ms) {
  return new Promise(function (resolve) {
    var done = false;
    var timer = setTimeout(function () {
      if (done) return;
      done = true;
      resolve({ status: 0, model: '', err: 'timeout' });
    }, ms || 20000);
    var f = probeFetchFn();
    if (!f) { clearTimeout(timer); resolve({ status: 0, model: '', err: 'no-fetch' }); return; }
    var init = {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(bodyObj)
    };
    try {
      if (cfg.dualKey) init.headers.Authorization = 'Bearer ' + cfg.dualKey;
    } catch (e) {}
    var p;
    try {
      p = f.call(HOST, url, init);
    } catch (e) {
      clearTimeout(timer); resolve({ status: 0, model: '', err: 'throw' }); return;
    }
    p.then(function (res) {
      var out = { status: res.status, model: '', err: '', ctx: '' };
      return res.text().then(function (t) {
        out.raw = String(t || '').slice(0, 4000);
        try {
          var j = JSON.parse(t);
          out.model = String(j.model || (j.candidates && j.candidates[0] && j.candidates[0].modelVersion) || '');
          if (j.error && j.error.message) out.err = String(j.error.message).slice(0, 120);
        } catch (e) {
          var m = /"(?:model|modelVersion)"\s*:\s*"([^"]{1,120})"/.exec(t || '');
          if (m) out.model = m[1];
          if (/131072|token count exceeds/i.test(t || '')) out.ctx = '131072';
        }
        return out;
      }).catch(function () { return out; });
    }).then(function (out2) {
      if (done) return;
      done = true;
      clearTimeout(timer);
      resolve(out2);
    }).catch(function () {
      if (done) return;
      done = true;
      clearTimeout(timer);
      resolve({ status: 0, model: '', err: 'network' });
    });
  });
}

/* 幽灵名探针：4xx ⇒ 按名分发（可验）；200 ⇒ 不读名字（回显） */
function runChannelVerify() {
  var base = String(cfg.dualBase || lastReqBase() || '').replace(/\/+$/, '');
  if (!base) return Promise.resolve({ ok: false, msg: '还没拿到渠道地址：先正常聊一轮，再来点这个' });
  var real = String(cfg.alias || (lastReq && lastReq.model) || 'gemini-4-argon');
  var ghost = real + '-zzz-nonexistent';
  var url = openAIUrl(base);
  var body = {
    model: ghost,
    messages: [{ role: 'user', content: 'ping' }],
    max_tokens: 16,
    stream: false
  };
  return probeOnce(url, body, 20000).then(function (r) {
    var echoes = null, note = '', why = '';
    var msg = String((r && r.err) || '');
    if (r.status >= 400 && r.status < 500 && r.status !== 429) {
      /* 4xx 不等于「按名分发」：401/403 是认证没过、402 是没钱，
         这两种根本没走到查模型那一步，不能拿来当证据。 */
      if (r.status === 401 || r.status === 403) {
        why = 'auth';
        note = '认证被拒（HTTP ' + r.status + '）：请求没走到「按名分发」这一步，判断不了';
      } else if (r.status === 402) {
        why = 'quota';
        note = '额度/计费被拒（HTTP 402）：判断不了';
      } else if (/model|not found|does not exist|unknown|no such|invalid/i.test(msg)) {
        why = 'rejected';
        echoes = false;
        note = '幽灵名被拒（HTTP ' + r.status + '）：网关按名分发，model 字段可作证据';
      } else {
        why = 'unclear';
        note = 'HTTP ' + r.status + ' 被拒，但错误与模型名无关' + (msg ? '（' + msg + '）' : '') + '：判断不了';
      }
    } else if (r.status === 200) {
      why = 'echo';
      echoes = true;
      note = '幽灵名也返回 200 ⇒ 网关不读 model，回传的 model 一律视为标签/回显';
    } else if (r.status === 0) {
      why = 'net';
      note = '探针失败：' + (r.err || '网络错误');
    } else {
      why = 'unclear';
      note = 'HTTP ' + r.status + '，无法定性（稍后重试）';
    }
    if (echoes !== null) setChState({ echoes: echoes, note: note });
    render();
    return { ok: echoes !== null, echoes: echoes, status: r.status, note: note,
      ghost: ghost, why: why, err: msg, raw: String((r && r.raw) || '').slice(0, 300) };
  });
}

/* ---------------- 别名钉死 ---------------- */

function aliasBaseName() {
  var m = String(cfg.alias || (lastReq && lastReq.model) || 'gemini-4-argon');
  return m.replace(/^(?:google\/|models\/|pg-)/i, '');
}

function aliasCandidates() {
  var x = aliasBaseName();
  var list = [
    x,
    'google/' + x,
    'models/' + x,
    'pg-' + x,
    x + '-high'
  ];
  var seen = {}, out = [];
  for (var i = 0; i < list.length; i++) {
    var v = list[i];
    if (!v || seen[v]) continue;
    seen[v] = 1;
    out.push(v);
  }
  return out.slice(0, 5);
}

function runAliasSweep() {
  var base = String(cfg.dualBase || lastReqBase() || '').replace(/\/+$/, '');
  if (!base) return Promise.resolve({ ok: false, msg: '先填反代 Base' });
  var url = openAIUrl(base);
  var cands = aliasCandidates();
  var rows = [];
  var chain = Promise.resolve();
  cands.forEach(function (name) {
    chain = chain.then(function () {
      var body = { model: name, messages: [{ role: 'user', content: 'ping' }], max_tokens: 16, stream: false };
      return probeOnce(url, body, 20000).then(function (r) {
        var ok = r.status === 200;
        var same = String(r.model || '').replace(/^models\//i, '').toLowerCase() === String(name).replace(/^models\//i, '').toLowerCase();
        rows.push({
          alias: name, status: r.status, model: r.model || '—',
          ctx: r.ctx, ok: ok, echo: ok && same
        });
      });
    });
  });
  return chain.then(function () {
    ALIAS_CACHE = rows;
    render();
    return { ok: true, rows: rows };
  });
}

/* ---------------- 瘦身报告（只读） ---------------- */

function slimReport(raw) {
  var body = null;
  try { body = JSON.parse(raw || (lastReq && lastReq.raw) || ''); } catch (e) { return null; }
  if (!body) return null;
  var msgs = Array.isArray(body.messages) ? body.messages : [];
  var text = '';
  for (var i = 0; i < msgs.length; i++) {
    var c = msgs[i] && msgs[i].content;
    if (typeof c === 'string') text += c + '\n\n';
  }
  var paras = text.split(/\n{2,}/).filter(function (p) { return p.trim().length >= 80; });
  var seen = {}, dupParas = 0, dupChars = 0;
  for (var j = 0; j < paras.length; j++) {
    var k = paras[j].trim().slice(0, 200);
    if (seen[k]) { dupParas++; dupChars += paras[j].length; } else seen[k] = 1;
  }
  var em = text.match(/(?:注意|强调|重要|必须|务必|切记)[：:，,]/g) || [];
  var sysCount = 0;
  for (var t = 0; t < msgs.length; t++) if (msgs[t] && msgs[t].role === 'system') sysCount++;
  return {
    chars: text.length,
    messages: msgs.length,
    systemCount: sysCount,
    dupParas: dupParas,
    dupChars: dupChars,
    emphasis: em.length,
    advice: (dupParas > 0 ? '有 ' + dupParas + ' 个重复段落（约 ' + dupChars + ' 字），可合并。' : '没有发现重复段落。') +
            (em.length > 12 ? ' 强调类词出现 ' + em.length + ' 次，密度偏高。' : '')
  };
}

/* ---------------- 路由率 KPI ---------------- */

function wilson(k, n) {
  if (!n) return { lo: 0, hi: 0, p: 0 };
  var z = 1.96, p = k / n;
  var d = 1 + z * z / n;
  var c = p + z * z / (2 * n);
  var a = z * Math.sqrt(p * (1 - p) / n + z * z / (4 * n * n));
  var lo = (c - a) / d, hi = (c + a) / d;
  return { p: p, lo: Math.max(0, lo), hi: Math.min(1, hi) };
}

function kpi() {
  var log = readLog() || [];
  var eff = 0, bad = 0;
  for (var i = 0; i < log.length; i++) {
    var r = log[i];
    if (!r) continue;
    if (r.internal) continue;   /* 插件请求不进路由率分母 */
    var conf = r.conf || 'C';
    if (conf !== 'A' && conf !== 'B') continue;
    if (r.code === 'skip') continue;   /* 不在检测范围的不进路由率 */
    if (r.code === 'aux') continue;    /* 辅助请求不是正文，不进分母 */
    if (r.code === 'unknown' || r.code === 'empty' || r.code === 'error') continue;
    eff++;
    if (r.code === 'diff' || r.code === 'thin' || r.code === 'echo') bad++;
  }
  var w = wilson(bad, eff);
  return { bad: bad, eff: eff, pct: eff ? Math.round(w.p * 1000) / 10 : 0, lo: Math.round(w.lo * 1000) / 10, hi: Math.round(w.hi * 1000) / 10, verifiable: verifiableCode() };
}

/* ---------------- 档位可观测性检查 ---------------- */

var LEVEL_TEST = { running: false, result: null };

function levelProbe(levelLabel, effort) {
  var base = String(cfg.dualBase || lastReqBase() || '').replace(/\/+$/, '');
  var url = openAIUrl(base);
  var body = {
    model: cfg.alias || (lastReq && lastReq.model) || 'gemini-4-argon',
    messages: [{ role: 'user', content: '用一句话解释：为什么天空是蓝色的？' }],
    max_tokens: 96,
    stream: false,
    reasoning_effort: effort
  };
  var t0 = nowMs();
  return probeOnce(url, body, 60000).then(function (r) {
    var dt = nowMs() - t0;
    var chars = 0;
    try {
      var j = JSON.parse(r.model ? '' : '');
    } catch (e) {}
    return { level: levelLabel, effort: effort, status: r.status, ms: dt, model: r.model, err: r.err };
  });
}

function runLevelCheck() {
  if (LEVEL_TEST.running) return Promise.resolve({ ok: false, msg: '正在跑' });
  var base = String(cfg.dualBase || lastReqBase() || '').replace(/\/+$/, '');
  if (!base) return Promise.resolve({ ok: false, msg: '先填反代 Base' });
  LEVEL_TEST.running = true;
  render();
  return levelProbe('高', 'high')
    .then(function (a) { return levelProbe('低', 'minimal').then(function (b) { return [a, b]; }); })
    .then(function (arr) {
      var a = arr[0], b = arr[1];
      var verdict = 'unknown', note = '';
      if (!a.status || !b.status) {
        note = '两档都没拿到响应（' + (a.err || b.err || '网络错误') + '），无法判断';
      } else if (a.status !== 200 && b.status !== 200) {
        note = '两档都非 200（' + a.status + '/' + b.status + '），无法判断';
      } else {
        var faster = b.ms > 0 && a.ms > 0 ? (a.ms / b.ms) : 0;
        if (faster >= 1.25 || faster <= 0.8) { verdict = 'honored'; note = '两档耗时差 ' + Math.round((faster - 1) * 100) + '%，参数看起来被尊重'; }
        else { verdict = 'ignored'; note = '两档耗时几乎相同（' + a.ms + 'ms vs ' + b.ms + 'ms），reasoning_effort 疑似被忽略'; }
      }
      LEVEL_TEST.running = false;
      LEVEL_TEST.result = { verdict: verdict, note: note, rows: arr };
      render();
      return { ok: true, verdict: verdict, note: note, rows: arr };
    })['catch'](function (e) {
      LEVEL_TEST.running = false;
      render();
      return { ok: false, msg: String(e && e.message || e) };
    });
}

/* ---------------- v7.4 锁定审计 / 外来护盾 ---------------- */

var LOCK_FIELDS = ['allow_fallbacks', 'openrouter_allow_fallbacks', 'openrouter_use_fallback', 'provider.allow_fallbacks'];
var LAST_AUDIT = null;
var LAST_FOREIGN = 0;

function readLockField(body, path) {
  if (!body || typeof body !== 'object') return undefined;
  if (path.indexOf('.') < 0) return Object.prototype.hasOwnProperty.call(body, path) ? body[path] : undefined;
  var parts = path.split('.');
  var cur = body;
  for (var i = 0; i < parts.length; i++) {
    if (!cur || typeof cur !== 'object' || !Object.prototype.hasOwnProperty.call(cur, parts[i])) return undefined;
    cur = cur[parts[i]];
  }
  return cur;
}

function lockAudit(body) {
  var rows = [], pinned = 0, present = 0;
  for (var i = 0; i < LOCK_FIELDS.length; i++) {
    var v = readLockField(body, LOCK_FIELDS[i]);
    var has = v !== undefined;
    var ok = has && v === false;
    if (has) present++;
    if (ok) pinned++;
    rows.push({ name: LOCK_FIELDS[i], present: has, locked: ok });
  }
  LAST_AUDIT = { total: LOCK_FIELDS.length, present: present, pinned: pinned, rows: rows };
  return LAST_AUDIT;
}

function auditLabel() {
  return LAST_AUDIT ? (LAST_AUDIT.pinned + '/' + LAST_AUDIT.total) : '—';
}

function auditColor() {
  if (!LAST_AUDIT) return 'gray';
  if (LAST_AUDIT.pinned === LAST_AUDIT.total) return 'ok';
  if (LAST_AUDIT.pinned > 0) return 'warn';
  return 'gray';
}

function foreignShield(body) {
  var msgs = body && Array.isArray(body.messages) ? body.messages : null;
  if (!msgs || !msgs.length) { LAST_FOREIGN = 0; return 0; }
  var hits = 0;
  var n = Math.min(12, msgs.length);
  for (var i = 0; i < n; i++) {
    var m = msgs[i];
    if (!m) continue;
    var t = typeof m.content === 'string' ? m.content : '';
    if (!t) continue;
    var c1 = (t.match(/<!--/g) || []).length;
    if (c1 >= 2) hits++;
    var c2 = (t.match(/^\[[a-zA-Z0-9_]{4,}\]:\s*#/gm) || []).length;
    if (c2 >= 2) hits++;
    var c3 = (t.match(/[\u200b\u200c\u200d\ufeff]{3,}/g) || []).length;
    if (c3 >= 2) hits++;
    if (/\[(?:IZUMI_ANTI_ROUTE|ANTI_ROUTE|GEMINI_ANTI_ROUTE)\]/i.test(t)) hits++;
  }
  LAST_FOREIGN = hits;
  return hits;
}

function foreignCount() { return LAST_FOREIGN; }

/* ===== 13_stats.js ===== */
/* ============================================================================
 * Anti-Route v7 — 13/Stats  渠道账本 / 指纹卡 / 记录导出 / A-B 对照
 * 原则：只做「度量与展示」。不碰生成请求、不 clone 200、不代替用户做决定。
 *   - 账本：按渠道累计有结论的轮次（不吃日志 40 条上限），给 wilson 区间
 *   - 指纹卡：把「这个渠道能不能验」聚成一段话，回显渠道自动降权
 *   - 导出：一段 <=1800 字的可粘贴文本 + 一行 base64 机读载荷
 *   - A/B：裸请求 vs 当前配置，各 2 次，只报倾向不报结论
 * ========================================================================== */

var LED_KEY = 'ar7.led';
var AB_STATE = { running: false, last: null };

function statBase() {
  try { return String(curBase() || '').replace(/\/+$/, ''); } catch (e) { return ''; }
}

/* 账本按 base 归并：同一个反代换 key 不该分家 */
function statKey() {
  var b = statBase();
  return b ? String(hashStr(b)).slice(0, 10) : 'local';
}

function readLed() {
  try {
    var o = JSON.parse(HOST.localStorage.getItem(LED_KEY) || '{}');
    return (o && typeof o === 'object') ? o : {};
  } catch (e) { return {}; }
}

function writeLed(o) {
  try { HOST.localStorage.setItem(LED_KEY, JSON.stringify(o)); } catch (e) {}
}

function ledEmpty() {
  return { n: 0, same: 0, diff: 0, thin: 0, echo: 0, blocked: 0, weak: 0, at: 0 };
}

function ledRow() {
  var all = readLed();
  var r = all[statKey()];
  if (!r || typeof r !== 'object') return ledEmpty();
  var o = ledEmpty();
  var keys = ['n', 'same', 'diff', 'thin', 'echo', 'blocked', 'weak', 'at'];
  for (var i = 0; i < keys.length; i++) {
    var v = Number(r[keys[i]]);
    o[keys[i]] = isFinite(v) ? v : 0;
  }
  return o;
}

/* 只收「有结论」的轮次：内部请求、C 级、unknown/empty/error 都不进分母。
   这条是路由率一直被高估的原因——分母混进来了不算数的轮次。 */
function ledAdd(rec) {
  try {
    if (!rec || rec.internal) return;
    var conf = rec.conf || 'C';
    var c = rec.code;
    if (c !== 'same' && c !== 'diff' && c !== 'thin' && c !== 'echo' && c !== 'blocked') return;
    var all = readLed();
    var k = statKey();
    var r = all[k];
    if (!r || typeof r !== 'object') r = ledEmpty();
    r.at = nowMs();
    if (conf === 'A' || conf === 'B') {
      r.n = Number(r.n || 0) + 1;
      r[c] = Number(r[c] || 0) + 1;
    } else {
      /* C 级也记，但只记「弱证据」一格：混进被换率就是把猜的当成的 */
      r.weak = Number(r.weak || 0) + 1;
    }
    all[k] = r;
    writeLed(all);
  } catch (e) {}
}

/* 被换率 = 不该出现的三种（被换 / 无思考 / 回显）占全部有结论轮次 */
function ledStat() {
  var r = ledRow();
  var bad = r.diff + r.thin + r.echo;
  var w = wilson(bad, r.n);
  return {
    n: r.n, bad: bad,
    pct: r.n ? Math.round(w.p * 1000) / 10 : 0,
    lo: Math.round(w.lo * 1000) / 10,
    hi: Math.round(w.hi * 1000) / 10,
    enough: r.n >= 5,
    row: r
  };
}

function ledLine() {
  var s = ledStat();
  if (!s.n) return '渠道账本：还没有有结论的轮次（先聊两轮）';
  var ci = s.enough ? ('（95% 区间 ' + s.lo + '–' + s.hi + '%）') : '（样本不足，先别当结论）';
  var weak = Number(s.row && s.row.weak || 0);
  return '渠道账本 n=' + s.n + ' · 被换 ' + s.pct + '%' + ci +
    (weak ? '，另有 ' + weak + ' 轮证据太弱未计入' : '');
}

/* ---------------- 渠道指纹卡（不做新存储，只把已有观测聚成一句话） ---------------- */

function fpCard() {
  var b = statBase() || '（未知渠道）';
  var st = { echoes: null };
  try { st = chState() || st; } catch (e) {}
  var ver = (st.echoes === true) ? '回显（名字对不上不能当证据）'
    : (st.echoes === false ? '可验（名字能当证据）' : '未验（先点「🔭 验渠道」）');
  var ali = 0;
  try { ali = (ALIAS_CACHE && ALIAS_CACHE.length) || 0; } catch (e2) { ali = 0; }
  var s = ledStat();
  var lines = [
    '🏷 渠道 ' + String(b).replace(/^https?:\/\//, '').slice(0, 42),
    '可验性：' + ver,
    '别名：' + (ali ? ali + ' 个可用' : '未扫（点「🏷 扫别名」）'),
    '账本：' + (s.n ? ('n=' + s.n + '，被换 ' + s.pct + '%' + (s.enough ? '' : '（样本不足）')) : '空'),
    '结论：' + (st.echoes === true
      ? '这个渠道会回显你的模型名，跨家族「被换」一律降级为「无法判定」。'
      : (st.echoes === false ? '名字可作为 B 级证据；跨家族且在响应体自述时才是 A 级。' : '未验渠道只有 C 级证据，别拿它下结论。'))
  ];
  return lines.join('\n');
}

/* ---------------- 记录导出 ---------------- */

function b64(s) {
  try {
    if (HOST.btoa) return HOST.btoa(unescape(encodeURIComponent(String(s))));
  } catch (e) {}
  return '';
}

function redact(s) {
  return String(s == null ? '' : s)
    .replace(/sk-[A-Za-z0-9_\-]{6,}/g, 'sk-***')
    .replace(/([?&](?:key|token|api_key)=)[^&\s]+/gi, '$1***');
}

function hhmm(ms) {
  try {
    var d = new Date(ms);
    return ('0' + d.getHours()).slice(-2) + ':' + ('0' + d.getMinutes()).slice(-2);
  } catch (e) { return '--:--'; }
}

/* 从新到旧取，直到 1800 字上限；宁可少几轮，也不要导出一段被截断的糊字 */
function exportText() {
  var log = readLog() || [];
  var s = ledStat();
  var head = [
    '卢克之光 V' + VERSION + ' · 记录导出',
    '渠道：' + (statBase() || '（未知）'),
    '账本：n=' + s.n + '，被换 ' + s.pct + '%（' + s.lo + '–' + s.hi + '%）' + (s.enough ? '' : ' 样本不足'),
    '---'
  ];
  var body = [];
  var used = head.join('\n').length;
  var picked = [];
  for (var i = log.length - 1; i >= 0; i--) {
    var r = log[i];
    if (!r) continue;
    var line = hhmm(r.at) + ' ' + (r.req || '—') + ' → ' + (r.obs || '—') +
      ' [' + (r.verdict || '?') + '/' + (r.conf || 'C') + ']' +
      (r.status ? ' HTTP' + r.status : '') +
      (r.chars ? ' ' + r.chars + '字' : '') +
      (r.internal ? ' (内部)' : '') +
      (r.note ? ' — ' + redact(r.note) : '');
    if (used + line.length + 1 > 1700) break;
    used += line.length + 1;
    body.push(line);
    picked.push({
      t: r.at, req: r.req, obs: r.obs, code: r.code, conf: r.conf,
      st: r.status, ch: r.chars, in: r.internal ? 1 : 0, n: redact(r.note)
    });
  }
  var payload = b64(JSON.stringify({
    v: VERSION, base: statBase(), led: { n: s.n, bad: s.bad, pct: s.pct }, rec: picked
  }));
  var out = head.join('\n') + '\n' + body.join('\n');
  if (payload) out += '\n#AR6LOG 1 ' + payload;
  return out;
}

/* ---------------- A/B 对照（裸请求 vs 当前配置） ---------------- */

function abBody(framed) {
  var b = {
    model: (cfg.alias || (lastReq && lastReq.model) || 'gemini-4-argon'),
    messages: [{ role: 'user', content: '说一句「好」。' }],
    max_tokens: 24,
    stream: false
  };
  if (!framed) return b;
  try {
    var p = planRequest(JSON.stringify(b), openAIUrl(statBase()), false);
    if (p && p.body && p.body !== JSON.stringify(b)) return JSON.parse(p.body);
  } catch (e) {}
  return b;
}

function abArm(framed) {
  var url = openAIUrl(statBase());
  return probeOnce(url, abBody(framed), 45000).then(function (r) {
    return { framed: framed, status: r.status, model: r.model || '', err: r.err || '' };
  });
}

/* 2×2：只报「配置有没有改变观测到的名字」，不下「谁更好」的结论 */
function abProbe() {
  if (AB_STATE.running) return Promise.resolve({ ok: false, msg: '正在跑' });
  if (!statBase()) return Promise.resolve({ ok: false, msg: '先填反代 Base' });
  AB_STATE.running = true;
  render();
  var seq = [false, true, false, true];
  var out = [];
  var step = function (i) {
    if (i >= seq.length) return Promise.resolve(out);
    return abArm(seq[i]).then(function (r) { out.push(r); return step(i + 1); });
  };
  return step(0).then(function (arr) {
    AB_STATE.running = false;
    var plain = [], framed = [];
    for (var i = 0; i < arr.length; i++) (arr[i].framed ? framed : plain).push(arr[i]);
    var same = function (a) { return a[0] && a[1] && a[0].model && a[0].model === a[1].model; };
    var note;
    if (!plain.length || !plain[0].model) note = '裸请求没拿到 model，对照不成立（可能渠道不写 model 字段）';
    else if (same(plain) && same(framed)) note = '两臂各自稳定，且配置没有改变观测名——配置是安全的';
    else if (same(plain) && !same(framed)) note = '开了配置后名字开始跳——配置可能碰到渠道兼容性';
    else note = '裸请求自己就不稳定——这不是配置的问题，是渠道本身在变';
    var res = { ok: true, plain: plain, framed: framed, note: note, at: nowMs() };
    AB_STATE.last = res;
    render();
    return res;
  })['catch'](function (e) {
    AB_STATE.running = false;
    render();
    return { ok: false, msg: String(e && e.message || e) };
  });
}

function abLine() {
  if (AB_STATE.running) return '⚖️ A/B 对照正在跑…';
  var r = AB_STATE.last;
  if (!r) return '⚖️ A/B 对照：还没跑过（各 2 次小请求，约 10 秒）';
  var f = function (a) {
    return a.map(function (x) { return (x.model || ('HTTP' + x.status)); }).join(' / ');
  };
  return '⚖️ 裸：' + f(r.plain) + ' ｜ 带配置：' + f(r.framed) + ' — ' + r.note;
}

/* ===== 7_jail.js ===== */
/* ============================================================================
 * Anti-Route v7.1 — 7/7 破甲（防空回 / 防截断）
 * 三档：off / safe（只事后补救，不改请求）/ strong（改请求 + 事后补救）
 * 铁律：任何一步失败都不许把请求弄挂；宁可不补，不能补错。
 * ========================================================================== */

var JAIL_GAP = 2500;          /* 两次自动续写的最小间隔 */
var JAIL_CHAIN_RESET = 20000; /* 这么久没有新续写，就认为上一轮结束了 */
var JAIL_WAIT_MAX = 24;       /* 等酒馆空下来，最多轮询 24 × 250ms */
var JAIL_RELOCK = 15000;      /* 自己续写后这么久之内，不再连环补 */

/* 预审框：一句 system 交代"接着写"，一句 user 要求"直接写"。
   措辞不用"审核/过审/安全/政策"这类词——这几个词本身就是在提示对方
   这是一段需要判定的文本，反而更容易被拦。 */
var JAIL_PRE_SYS = '接着上一段往下写：从断开的那句起笔，写正文，不必复述前情，也不必解释。';
var JAIL_PRE_USR = '【直接续写】';
/* 输出契约：贴在最后一条用户消息尾部的一句话 */
var JAIL_TAIL_TXT = '【直接续写】';
/* 预设自带标记：只扫 system 段文本；命中就跳过 token 保底，其余照做（<content> 是正文包裹标签，不能算） */
var JAIL_OWN_RE = /Reply directly|editorial system|<Master_input>/;
/* 拒绝句式（只在很短的回包里判，长文里出现这些词是剧情，不是拒绝） */
/* v0.2：区分「安全层拒绝」与「语气上拒绝工作」——前者续写一万次也没用，得换渠道 */
var JAIL_SAFETY_RE = /(safety|content policy|prohibited|policy violation|safety system|敏感|违规|安全策略|内容政策|不适宜|未成年|underage|minor)/i;

var JAIL_REFUSE_RE = /(很抱歉|抱歉[，,]|对不起[，,]|无法(?:继续|提供|协助|参与|生成|完成)|不能(?:继续|提供|协助)|我(?:不能|无法|不会)(?:提供|协助|继续)|As an AI|I(?:'m| am) (?:sorry|unable)|I (?:can(?:'|no)t|cannot) (?:help|assist|continue))/i;

var JL = { lock: false, lockAt: 0, count: 0, at: 0, key: '', seq: 0, total: 0, firstAt: 0, selfAt: 0,
  /* v0.2：补了几次、补完有没有好转——没有度量的自动重试就是赌博 */
  try: 0, ok: 0, pendKey: '', lastWhy: '' };

/* ---------------- 档位 ---------------- */

function jailLabel() {
  if (!cfg) return '关';
  if (cfg.jail === 'strong') return '超级';
  if (cfg.jail === 'safe') return '普通';
  return '关';
}

function jailNext() {
  if (!cfg || cfg.jail === 'off' || !cfg.jail) return 'safe';
  if (cfg.jail === 'safe') return 'strong';
  return 'off';
}

function jailChipLabel() {
  return '🩹 破甲:' + jailLabel();
}

function jailStatus() {
  if (!cfg || cfg.jail === 'off') return '';
  if (!cfg.enabled) return '⚠ 防护总开关关着：破甲不会生效';
  if (cfg.safe) return '⚠ 安全模式开着：补救不会触发';
  if (!cfg.observe) return '⚠ 观察器关着：补救不会触发（点开「观察器」）';
  var s = '就绪';
  if (JL.count) s += '（本轮已补 ' + JL.count + ' 次）';
  return s;
}

/* ---------------- 强力档：改请求 ---------------- */

function jailMsgArray(body) {
  if (!body || typeof body !== 'object') return null;
  if (Array.isArray(body.messages)) return body.messages;
  try {
    if (body.request && typeof body.request === 'object' && Array.isArray(body.request.messages)) return body.request.messages;
  } catch (e) {}
  return null;
}

function jailLastUserIdx(arr) {
  if (!arr || !arr.length) return -1;
  for (var i = arr.length - 1; i >= 0; i--) {
    if (arr[i] && arr[i].role === 'user') return i;
  }
  return -1;
}

function jailAppendAt(arr, idx, txt) {
  var m = arr[idx];
  if (!m) return false;
  var cur = textOfMsg(m);
  if (cur.indexOf(txt) >= 0) return false;
  setMsgText(m, cur ? (cur + '\n\n' + txt) : txt);
  return true;
}

/* 只取 system 段文本（各家的字段位置不一样）；正文 user/assistant 一律不扫，避免误判 */
function jailSysText(body) {
  var parts = [];
  function push(v) {
    if (typeof v === 'string') { if (v) parts.push(v); return; }
    if (Array.isArray(v)) {
      for (var j = 0; j < v.length; j++) push(v[j]);
      return;
    }
    if (!v || typeof v !== 'object') return;
    if (typeof v.text === 'string' && v.text) parts.push(v.text);
    if (Array.isArray(v.parts)) push(v.parts);
  }
  try {
    var arr = jailMsgArray(body);
    if (arr && arr.length) {
      for (var i = 0; i < arr.length; i++) {
        if (arr[i] && arr[i].role === 'system') push(textOfMsg(arr[i]));
      }
    }
  } catch (e1) {}
  try {
    push(body.system);
    push(body.systemInstruction);
    var rq = body.request;
    if (rq && typeof rq === 'object' && !Array.isArray(rq)) {
      push(rq.system);
      push(rq.systemInstruction);
    }
  } catch (e2) {}
  return parts.join('\n');
}

function jailPatchBody(body) {
  var out = [];
  if (!cfg || !cfg.enabled || cfg.jail !== 'strong') return out;
  if (!body || typeof body !== 'object' || Array.isArray(body)) return out;

  var own = false;
  try { own = JAIL_OWN_RE.test(jailSysText(body)); } catch (e0) { own = false; }
  if (own) out.push('破甲跳过token(预设已自带)');

  /* 1) 保底 token：只加不减；字段缺失时不动（默认上限未知，乱补可能反而砍短） */
  if (cfg.jailTok && !own) {
    var floorTok = 2048;
    var names = ['max_tokens', 'max_completion_tokens', 'maxTokens', 'max_output_tokens'];
    var i, k;
    for (i = 0; i < names.length; i++) {
      k = names[i];
      if (typeof body[k] === 'number' && isFinite(body[k]) && body[k] < floorTok) {
        body[k] = floorTok; out.push('保底token ' + k + '→' + floorTok);
      }
    }
    try {
      var gc = body.generationConfig;
      if (gc && typeof gc.maxOutputTokens === 'number' && isFinite(gc.maxOutputTokens) && gc.maxOutputTokens < floorTok) {
        gc.maxOutputTokens = floorTok; out.push('保底token maxOutputTokens→' + floorTok);
      }
    } catch (e1) {}
    try {
      var rq = body.request;
      if (rq && typeof rq === 'object' && !Array.isArray(rq)) {
        for (i = 0; i < names.length; i++) {
          k = names[i];
          if (typeof rq[k] === 'number' && isFinite(rq[k]) && rq[k] < floorTok) {
            rq[k] = floorTok; out.push('保底token request.' + k + '→' + floorTok);
          }
        }
      }
    } catch (e2) {}
  }

  /* 2) 原生解安全：只对 gemini 系发，别的家写这个字段可能 400 */
  if (cfg.jailSafe) {
    var mdl = String(body.model || cfg.alias || '');
    if (isGeminiLike(mdl) && !body.safetySettings) {
      var cats = ['HARM_CATEGORY_HARASSMENT', 'HARM_CATEGORY_HATE_SPEECH', 'HARM_CATEGORY_SEXUALLY_EXPLICIT',
        'HARM_CATEGORY_DANGEROUS_CONTENT', 'HARM_CATEGORY_CIVIC_INTEGRITY'];
      var ss = [];
      for (i = 0; i < cats.length; i++) ss.push({ category: cats[i], threshold: 'BLOCK_NONE' });
      body.safetySettings = ss;
      out.push('解安全 BLOCK_NONE×' + ss.length);
    }
  }

  /* 3) 预审框 + 输出契约：只贴在最后一条 user 消息上，不动消息顺序、不加连续 user */
  var arr = jailMsgArray(body);
  if (arr && arr.length) {
    var ui = jailLastUserIdx(arr);
    if (ui >= 0) {
      if (cfg.jailPre) {
        if (jailAppendAt(arr, ui, JAIL_PRE_USR)) {
          var ins = { role: 'system', content: JAIL_PRE_SYS };
          arr.splice(ui, 0, ins);
          ui++;                       /* 原那条 user 往后挪了一位 */
          out.push('预审框');
        }
      }
      if (cfg.jailText) {
        if (jailAppendAt(arr, ui, JAIL_TAIL_TXT)) out.push('输出契约');
      }
    }
  }

  return out;
}

/* ---------------- 判定：空回 / 截断 / 硬拒 ---------------- */

function jailTruncWhy(tail, chars) {
  var t = String(tail || '');
  if (!t) return '';
  var flat = t.replace(/\s+$/, '');
  if (!flat) return '';

  var fences = flat.split('```').length - 1;
  if (fences % 2 === 1) return '代码块未闭合';

  var last = flat.charAt(flat.length - 1);
  if ('，,、：:；;'.indexOf(last) >= 0) return '停在逗号/冒号';
  if ('「『（【《“‘'.indexOf(last) >= 0) return '停在开引号/开括号';
  if ('。！？…”』」）】》.!?～~*'.indexOf(last) >= 0) return '';

  /* 长文而且尾部一整段没有任何句末标点：多半是被砍在半句话上 */
  if (chars > 800) {
    var seg = flat.slice(-120);
    if (!/[。！？…”』」）】》\.!?]/.test(seg)) return '尾部没有句末标点';
  }
  return '';
}

function jailInspect(ev) {
  if (!ev) return null;
  var chars = Number(ev.outputChars || 0);
  var mc = (typeof ev.mesChars === 'number') ? ev.mesChars : chars;
  var tail = String(ev.tail || '');

  /* v8.29：数据库/填表这类内部请求不写聊天产物，判「无产物」而不是空回 */
  if (ev.internal) return { code: 'none', note: '内部请求（数据库/填表）：没有聊天产物' };
  if (ev.blocked) return { code: 'refuse', note: '上游拦截 ' + ev.blocked };
  /* v8.29：响应体已经取到正文（聊天记录还没提交）时，这不是空回 */
  if (mc < 1 && ev.sawText) return { code: 'ok', note: '' };
  if (mc < 1 || !tail) return { code: 'empty', note: '这一条没有正文' };
  /* 判「短」看本轮增量：续写后 mesChars 是整条消息，3000 字里续出 200 字拒绝也要判出来 */
  var delta = (chars > 0) ? chars : mc;
  if (delta < 300 && JAIL_REFUSE_RE.test(tail)) {
    var hard = JAIL_SAFETY_RE.test(tail);
    return {
      code: 'refuse',
      hard: !!hard,
      note: hard ? '安全层拒绝（换渠道才有用，续写不会变）' : '像是拒绝（可能只是这段没接上）'
    };
  }

  var why = jailTruncWhy(tail, mc);
  if (why) return { code: 'trunc', note: '像是截断（' + why + '）' };
  return { code: 'ok', note: '' };
}

/* ---------------- 事后补救：自动续写 ---------------- */

function jailLastAi() {
  var ctx = stCtx();
  if (!ctx || !Array.isArray(ctx.chat) || !ctx.chat.length) return null;
  var idx = ctx.chat.length - 1;
  var msg = ctx.chat[idx];
  if (!msg || msg.is_user) return null;
  return { ctx: ctx, idx: idx, msg: msg };
}

function jailGate(key) {
  var t = nowMs();
  if (JL.lock && t - JL.lockAt > JAIL_RELOCK) JL.lock = false;   /* 锁自己解，别永久卡死 */
  if (!JL.firstAt || t - JL.firstAt > 60000) { JL.firstAt = t; JL.total = 0; }
  if (JL.total >= 6) return { ok: false, why: 'rate' };          /* 一分钟 6 次：看着像死循环 */
  if (JL.key !== key) { JL.key = key; JL.count = 0; JL.at = 0; }
  if (JL.at && t - JL.at > JAIL_CHAIN_RESET) JL.count = 0;
  if (JL.lock) return { ok: false, why: 'lock' };
  if (JL.at && t - JL.at < JAIL_GAP) return { ok: false, why: 'gap' };
  var max = 1;
  if (JL.count >= max) return { ok: false, why: 'max' };
  return { ok: true };
}

function jailTrigger() {
  var ctx = stCtx();
  if (ctx) {
    if (typeof ctx.executeSlashCommandsWithOptions === 'function') {
      return { kind: '/continue', fn: function () { return ctx.executeSlashCommandsWithOptions('/continue'); } };
    }
    if (typeof ctx.executeSlashCommands === 'function') {
      return { kind: '/continue(旧)', fn: function () { return ctx.executeSlashCommands('/continue'); } };
    }
  }
  var btn = DOC && DOC.getElementById && DOC.getElementById('option_continue');
  if (btn) return { kind: '按钮', fn: function () { try { btn.click(); } catch (e) {} return null; } };
  return null;
}

function jailFire() {
  var trig = jailTrigger();
  if (!trig) {
    JL.lock = false;
    banner('🩹 找不到续写入口，请手动点「继续」', 'warn');
    return;
  }
  var seq0 = JL.seq;
  JL.lock = true;
  JL.lockAt = nowMs();
  JL.at = nowMs();
  JL.total++;
  var done = false;
  function release() {
    if (done) return;
    done = true;
    JL.lock = false;
  }
  try {
    var r = trig.fn();
    /* v8.29：这一枪是我们自己打的——记下时间，别把它自己的收尾再当成空回去补 */
    JL.selfAt = nowMs();
    if (r && typeof r.then === 'function') {
      r.then(function (res) {
        release();
        var s = String(res == null ? '' : res);
        if (/cannot run|生成中|being generated/i.test(s)) banner('🩹 酒馆说还在生成，这轮不补了', 'warn');
      })['catch'](function (e) {
        release();
        banner('🩹 续写出错：' + String(e && e.message || e).slice(0, 60) + '（可手动点「继续」）', 'warn');
      });
    } else {
      setTimeout(release, 8000);
    }
    /* 发出去 8 秒还没有新请求，说明入口没生效 */
    setTimeout(function () {
      if (JL.seq === seq0 && !isBusy()) banner('🩹 续写没发出去，请手动点「继续」', 'warn');
    }, 8000);
  } catch (e) {
    release();
    banner('🩹 续写调用失败：' + String(e && e.message || e).slice(0, 60), 'warn');
  }
}

/* ---- 手动确认：不点就不补 ---- */
var JAIL_ASK = { at: 0, code: '', key: '' };

/* v0.3：超级破甲会改你发出去的请求，开启前必须过这一道 */
function jailSuperHTML() {
  var h = '';
  h += '<style>#ar6-card,#ar6-card *{box-sizing:border-box;min-width:0}</style>';
  h += '<div id="ar6-card" style="' + cardOverlayCss() + 'z-index:2147483600;background:rgba(1,4,9,.9);font-family:system-ui,-apple-system,\'Segoe UI\',sans-serif">';
  h += '<div style="width:402px;max-width:calc(100vw - 20px);max-height:' + cardBoxMaxH(88) + ';overflow:auto;background:#0d1117;color:#e6edf3;border:1px solid #30363d;border-radius:16px;box-shadow:0 12px 48px rgba(0,0,0,.6)">';
  h += '<div style="padding:16px">';
  h += '<div style="display:inline-block;font-size:11px;padding:3px 8px;border-radius:999px;background:#f8514922;color:#f85149;border:1px solid #f8514955;margin-bottom:8px">谨慎使用</div>';
  h += '<div style="font-size:19px;font-weight:700;line-height:1.35;color:#f85149">开启「超级破甲」？</div>';
