}

/* ---------------- 面板 ---------------- */

function counts() {
  var log = readLog();
  var c = { same: 0, diff: 0, thin: 0, unknown: 0, other: 0 };
  for (var i = 0; i < log.length; i++) {
    var k = log[i].code;
    if (k === 'same') c.same++;
    else if (k === 'diff') c.diff++;
    else if (k === 'thin') c.thin++;
    else if (k === 'unknown') c.unknown++;
    else c.other++;
  }
  return c;
}

function panelStyle(mode, mini) {
