    '</div>';

  /* 自检卡与身份筛选卡：V1.3 起入口已删，这两块永远只会显示「未跑」，一并从面板撤掉
     （runSelfTest / runIdentityProbe 仍保留导出，需要时可在控制台调用） */
  var lg = readLog() || [];
