  }
  var next = !oocOnOf(item);
  cfg[key] = next;
  try { saveCfg(); } catch (e1) {}
  render();
  banner((OOC_LABEL[item] || item) + '：' + (next ? '开' : '关'), next ? 'ok' : 'gray');
  if (!next) return;
  /* 刚打开：预设里要是也管了这一项，先问一句用谁的 */
